const GLOSS={
 // фонетика и орфоэпия: составные термины — в начале, чтобы автоссылка находила их раньше общих («двойные согласные» раньше «согласный»)
 fonetika:{t:'Фонетика',d:'Раздел науки о языке, который изучает звуки речи, слоги и ударение.',ex:'звуки [а], [м\'], слоги ма-ма, ударение в слове ма́ма',cat:'Фонетика и орфоэпия',f:'фонетик(?:а|и|е|у|ой)',at:'zv1',ch:'zvuki',see:['zvuk', 'grafika', 'slog']},
 grafika:{t:'Графика',d:'Раздел науки о языке, который изучает буквы и то, как ими обозначают звуки на письме.',ex:'мягкость [л\'] обозначает ь или гласная буква: лень, лёд',cat:'Фонетика и орфоэпия',f:'графика|графики|графике|графику|графикой',at:'zv1',ch:'zvuki',see:['bukva', 'alfavit', 'fonetika']},
 alfavit:{t:'Алфавит',d:'Все буквы языка, расположенные в принятом порядке. В русском алфавите 33 буквы.',ex:'а, б, в, г, д, е, ё, ж, з …',cat:'Фонетика и орфоэпия',f:'алфавит(?:а|у|ом|е)?',at:'zv1',ch:'zvuki',see:['bukva', 'grafika']},
 transkr:{t:'Транскрипция',d:'Запись слова так, как оно звучит: в квадратных скобках, мягкость — знаком \', ударение — знаком ́.',ex:'ёж [йо́ш], день [д\'е́н\']',cat:'Фонетика и орфоэпия',f:'транскрипци(?:я|и|ю|ей)',at:'zv1',ch:'zvuki',see:['zvuk', 'fon_razb']},
 zvonk:{t:'Звонкий согласный',d:'Согласный, который произносится с голосом и шумом.',ex:'[б], [в], [г], [д], [ж], [з]; сонорные [л], [м], [н], [р], [й]',cat:'Фонетика и орфоэпия',f:'звонк(?:ий|ие|их|ого|ому|им|ими)',at:'zv3',ch:'zvuki',see:['gluh', 'parn', 'soglasn']},
 gluh:{t:'Глухой согласный',d:'Согласный, который произносится одним шумом, без голоса.',ex:'[п], [ф], [к], [т], [ш], [с]; [х], [ц], [ч\'], [щ\']',cat:'Фонетика и орфоэпия',f:'глух(?:ой|ие|их|ого|ому|им|ими)',at:'zv3',ch:'zvuki',see:['zvonk', 'parn', 'oglush']},
 parn:{t:'Парные и непарные согласные',d:'Парные — согласные, которые различаются только одним признаком (звонкостью-глухостью или твёрдостью-мягкостью): [б]–[п], [л]–[л\']. У непарных такой пары нет.',ex:'парные [д]–[т]; непарные по звонкости [л], [м], [ц], [ч\']',cat:'Фонетика и орфоэпия',f:'(?:не)?парн(?:ый|ые|ых|ого|ому|ым|ыми)',at:'zv3',ch:'zvuki',see:['zvonk', 'gluh', 'tverd']},
 tverd:{t:'Твёрдый согласный',d:'Согласный, который произносится без подъёма средней части языка к нёбу. Всегда твёрдые: [ж], [ш], [ц].',ex:'[л] в слове лук; [ж] в слове жизнь',cat:'Фонетика и орфоэпия',f:'тв[её]рд(?:ый|ые|ых|ого|ому|ым|ыми)',at:'zv1',ch:'zvuki',see:['myagk', 'parn', 'soglasn']},
 myagk:{t:'Мягкий согласный',d:'Согласный, который произносится с подъёмом средней части языка к нёбу; в транскрипции — знак \'. Всегда мягкие: [ч\'], [щ\'], [й\'].',ex:'[л\'] в слове люк; [ч\'] в слове час',cat:'Фонетика и орфоэпия',f:'мягк(?:ий|ие|их|ого|ому|им|ими)(?!\\s+знак)',at:'zv1',ch:'zvuki',see:['tverd', 'parn', 'soglasn']},
 sonor:{t:'Сонорные согласные',d:'Звонкие непарные согласные, в которых голос сильнее шума: [л], [м], [н], [р], [й\'] (и их мягкие пары).',ex:'лампа, мир, нора, рама',cat:'Фонетика и орфоэпия',f:'сонорн[а-яё]*',at:'zv3',ch:'zvuki',see:['zvonk', 'shum']},
 shum:{t:'Шумные согласные',d:'Все согласные, кроме сонорных: в них шум сильнее голоса или есть только шум.',ex:'[б], [п], [з], [с], [ш], [х]',cat:'Фонетика и орфоэпия',f:'шумн(?:ый|ые|ых|ого|ому|ым|ыми)',at:'sl2',ch:'slog',see:['sonor', 'soglasn']},
 razdel:{t:'Разделительные ъ и ь',d:'Знаки, которые показывают, что следующая гласная буква е, ё, ю, я обозначает два звука: [й\'] и гласный.',ex:'подъезд, съёмка; семья, вьюга',cat:'Фонетика и орфоэпия',f:'разделительн(?:ый|ого|ому|ым|ом|ые|ых)',at:'zv4',ch:'znaki',see:['bukva', 'myagk']},
 pozic:{t:'Сильная и слабая позиция',d:'Сильная позиция — та, где звук слышен ясно и не меняется (гласный под ударением, согласный перед гласным). В слабой позиции звук изменяется, и написание надо проверять.',ex:'во́ды — сильная позиция, вода́ — слабая; дубы — сильная, дуб [ду́п] — слабая',cat:'Фонетика и орфоэпия',f:'(?:сильн|слаб)(?:ая|ой|ую) позици[а-яё]*',at:'zv2',ch:'zvuki',see:['oglush', 'bezud', 'orfogramma']},
 oglush:{t:'Оглушение',d:'Замена звонкого согласного парным глухим в конце слова и перед глухим согласным.',ex:'дуб [ду́п], ложка [ло́шка]',cat:'Фонетика и орфоэпия',f:'оглушени[а-яё]*|оглуша[а-яё]*',at:'zv5',ch:'zvuki',see:['ozvonch', 'pozic', 'gluh']},
 ozvonch:{t:'Озвончение',d:'Замена глухого согласного парным звонким перед звонким шумным согласным.',ex:'просьба [про́з\'ба], сделать [зд\'е́лат\']',cat:'Фонетика и орфоэпия',f:'озвончени[а-яё]*|озвонча[а-яё]*',at:'zv5',ch:'zvuki',see:['oglush', 'pozic', 'zvonk']},
 neproizn:{t:'Непроизносимый согласный',d:'Согласная буква, которая пишется, но звуком не произносится.',ex:'солнце [со́нцэ], чувство [ч\'у́ства]',cat:'Фонетика и орфоэпия',f:'непроизносим[а-яё]*',at:'zv5',ch:'soglas',see:['bukva', 'zvuk']},
 fon_razb:{t:'Фонетический разбор',d:'Разбор слова по звукам: слоги и ударение, характеристика каждого звука, число букв и звуков, транскрипция.',ex:'ель [й\'э́л\'] — 1 слог; 3 буквы, 3 звука',cat:'Фонетика и орфоэпия',f:'фонетическ(?:ий|ого|ому|им|ом) разбор[а-яё]*',at:'zv6',ch:'zvuki',see:['transkr', 'zvuk', 'slog']},
 slog:{t:'Слог',d:'Звук или несколько звуков, которые произносятся одним толчком воздуха. Сколько в слове гласных, столько и слогов.',ex:'ма-ли-на — три слога',cat:'Фонетика и орфоэпия',f:'слог(?:а|у|ом|е|и|ов|ам|ами|ах)?',at:'zv1',ch:'slog',see:['sloobr', 'otkr', 'perenos']},
 sloobr:{t:'Слогообразующий звук',d:'Звук, который образует слог. В русском языке это гласный.',ex:'в слове окно два слогообразующих звука: [а], [о]',cat:'Фонетика и орфоэпия',f:'слогообразующ[а-яё]*',at:'sl1',ch:'slog',see:['slog', 'glasn']},
 otkr:{t:'Открытый и закрытый слог',d:'Открытый слог кончается гласным звуком, закрытый — согласным.',ex:'ма-ма — оба открытые; дом — закрытый; чай-ка — первый закрытый',cat:'Фонетика и орфоэпия',f:'(?:открыт|закрыт)(?:ый|ые|ых|ого|ому|ым|ыми|ом) слог[а-яё]*',at:'sl2',ch:'slog',see:['slog']},
 perenos:{t:'Перенос',d:'Перенесение части слова с одной строки на другую по правилам: по слогам, не оставляя и не перенося одну букву, не отрывая й, ь, ъ от предыдущей буквы.',ex:'ко-ро-ва, чай-ка, кас-са, конь-ки',cat:'Фонетика и орфоэпия',f:'перенос(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'sl3',ch:'slog',see:['slog', 'dvoin', 'stech']},
 dvoin:{t:'Двойные согласные',d:'Две одинаковые согласные буквы подряд. При переносе их разделяют.',ex:'кас-са, ван-на',cat:'Фонетика и орфоэпия',f:'двойн(?:ые|ых|ым|ыми) согласн[а-яё]*',at:'sl4',ch:'slog',see:['perenos', 'stech']},
 stech:{t:'Стечение согласных',d:'Две или больше разные согласные подряд. При переносе их можно разделить по-разному; если среди них есть ь — только сразу после него.',ex:'се-стра, сес-тра, сест-ра; паль-то',cat:'Фонетика и орфоэпия',f:'стечени[а-яё]* согласн[а-яё]*',at:'sl4',ch:'slog',see:['perenos', 'dvoin']},
 raznomest:{t:'Разноместное ударение',d:'Ударение, которое в разных словах может падать на любой слог: в русском языке нет постоянного места ударения.',ex:'ма́ма, кино́, молоко́, во́рон',cat:'Фонетика и орфоэпия',f:'разноместн[а-яё]*',at:'ud2',ch:'udar',see:['udar', 'podvizh']},
 podvizh:{t:'Подвижное и неподвижное ударение',d:'Подвижное ударение переходит с одного слога на другой в формах одного слова, неподвижное остаётся на месте.',ex:'подвижное: голова́ — го́лову; неподвижное: кни́га — кни́ги',cat:'Фонетика и орфоэпия',f:'(?:не)?подвижн(?:ое|ого|ому|ым|ом) ударени[а-яё]*',at:'ud2',ch:'udar',see:['udar', 'raznomest']},
 omograf:{t:'Омографы',d:'Слова, которые пишутся одинаково, а различаются ударением и значением.',ex:'за́мок — замо́к, му́ка — мука́',cat:'Фонетика и орфоэпия',f:'омограф[а-яё]*',at:'ud3',ch:'omon',see:['udar']},
 // лексика: омонимы, синонимы, антонимы, паронимы (глава «Омонимы, синонимы, антонимы»)
 omonim:{t:'Омонимы',d:'Разные слова, которые одинаково звучат и пишутся, но не связаны по значению. В словаре — отдельные статьи с цифрами.',ex:'лук (растение) — лук (оружие); ключ (от замка) — ключ (родник)',cat:'Лексика',f:'омоним[а-яё]*',at:'lk1',ch:'omon',see:['omofon','omograf','omoforma','kalambur']},
 omofon:{t:'Омофоны',d:'Слова, которые звучат одинаково, а пишутся по-разному.',ex:'луг — лук, плод — плот, бал — балл',cat:'Лексика',f:'омофон[а-яё]*',at:'om1',ch:'omon',see:['omonim','omograf','oglush']},
 omoforma:{t:'Омоформы',d:'Разные слова, которые совпадают только в одной форме и отвечают на разные вопросы.',ex:'печь (что?) — печь (что делать?); мой (чей?) — мой (что делай?)',cat:'Лексика',f:'омоформ[а-яё]*',at:'om1',ch:'omon',see:['omonim']},
 kalambur:{t:'Каламбур',d:'Игра слов: шутка, построенная на омонимах, значениях многозначного слова или похожих по звучанию словах.',ex:'Какой лук не кладут в суп? — Тот, из которого стреляют. «Защитник вольности и прав / В сём случае совсем неправ» (А. С. Пушкин)',cat:'Лексика',f:'каламбур[а-яё]*',at:'om1',ch:'omon',see:['omonim','paronim']},
 sin_ryad:{t:'Синонимический ряд',d:'Группа синонимов; первым стоит опорное слово — доминанта, самое общее и нейтральное.',ex:'идти, шагать, брести, плестись',cat:'Лексика',f:'синонимическ(?:ий|ого|ому|им|ом|ие|их) ряд[а-яё]*',at:'om2',ch:'omon',see:['sinonim','dominanta']},
 sinonim:{t:'Синонимы',d:'Слова, близкие или одинаковые по значению, но разные по звучанию; отвечают на один и тот же вопрос. Различаются оттенком значения, окраской, сочетаемостью.',ex:'смелый — храбрый — отважный; смотреть — глядеть',cat:'Лексика',f:'синоним[а-яё]*',at:'lk1',ch:'omon',see:['sin_ryad','dominanta','antonim','paronim']},
 dominanta:{t:'Доминанта',d:'Опорное слово синонимического ряда: называет общее значение ряда, нейтрально и уместно в любой речи.',ex:'в ряду «упасть, свалиться, шлёпнуться» доминанта — упасть',cat:'Лексика',f:'доминант[а-яё]*',at:'om2',ch:'omon',see:['sin_ryad','sinonim']},
 antonim:{t:'Антонимы',d:'Слова с противоположным значением, отвечающие на один вопрос. Бывают однокоренные и разнокоренные; у многозначного слова к каждому значению свой антоним.',ex:'день — ночь, вход — выход, старый дом — новый, старый человек — молодой',cat:'Лексика',f:'антоним[а-яё]*',at:'lk1',ch:'omon',see:['antiteza','sinonim','oksimoron']},
 antiteza:{t:'Антитеза',d:'Резкое противопоставление в речи, обычно с помощью антонимов.',ex:'«Волна и камень, / Стихи и проза, лёд и пламень» (А. С. Пушкин)',cat:'Лексика',f:'антитез[а-яё]*',at:'om3',ch:'vyraz',see:['antonim','oksimoron']},
 oksimoron:{t:'Оксюморон',d:'Соединение слов с противоположным смыслом в одном сочетании.',ex:'горькая радость, звонкая тишина, «Мёртвые души» (название поэмы Н. В. Гоголя)',cat:'Лексика',f:'оксюморон[а-яё]*',at:'om3',ch:'vyraz',see:['antonim','antiteza']},
 paronim:{t:'Паронимы',d:'Однокоренные слова, похожие по звучанию, но разные по значению и сочетаемости. Смешение паронимов — речевая ошибка.',ex:'надеть (что?) — одеть (кого?); сытый — сытный; абонент — абонемент',cat:'Лексика',f:'пароним[а-яё]*',at:'om4',ch:'omon',see:['sinonim','omofon','pleonazm']},
 pleonazm:{t:'Плеоназм',d:'Речевая ошибка: лишнее слово, которое повторяет смысл соседнего.',ex:'памятный сувенир, свободная вакансия, моя автобиография',cat:'Лексика',f:'плеоназм[а-яё]*',at:'lk5',ch:'leknorm',see:['tavtol','paronim']},
 tavtol:{t:'Тавтология',d:'Повтор однокоренных слов рядом, обычно речевая ошибка.',ex:'рассказать рассказ, спросить вопрос (правильно: задать вопрос)',cat:'Лексика',f:'тавтологи[а-яё]*',at:'lk5',ch:'leknorm',see:['pleonazm','sinonim']},
 orfoepia:{t:'Орфоэпия',d:'Раздел науки о языке о правильном литературном произношении и ударении.',ex:'звони́т, догово́р, кварта́л',cat:'Фонетика и орфоэпия',f:'орфоэпи(?:я|и|ю|ей)',at:'ud4',ch:'proizn',see:['orfoep_norma', 'orfoep_sl', 'norma']},
 orfoep_norma:{t:'Орфоэпическая норма',d:'Принятые в литературном языке правила произношения и ударения.',ex:'торт — то́рты (не торты́)',cat:'Фонетика и орфоэпия',f:'орфоэпическ(?:ая|ой|ую|ие|их) норм[а-яё]*',at:'ud4',ch:'proizn',see:['orfoepia', 'norma']},
 orfoep_sl:{t:'Орфоэпический словарь',d:'Словарь, в котором указаны правильное ударение и произношение слов.',ex:'в нём проверяют: кра́ны, балова́ть',cat:'Фонетика и орфоэпия',f:'орфоэпическ(?:ий|ого|ому|им|ом) словар[а-яё]*',at:'ud4',ch:'proizn',see:['orfoepia']},
 bezud:{t:'Безударный гласный',d:'Гласный звук в слоге без ударения. Он слышится нечётко: на месте буквы о звучит [а], на месте е и я после согласных (кроме ж, ш, ц) — звук, близкий к [и]. Чтобы услышать гласный ясно, слово изменяют так, чтобы он оказался под ударением.',ex:'вода [вада́] — во́ды; река [р\'ика́] — ре́ки',cat:'Орфография',f:'безударн[а-яё]*',at:'zv2',ch:'zvuki',see:['udar','glasn','pozic']},
 bud:{t:'Будущее время',d:'Время действия, которое произойдёт после момента речи. Причастий будущего времени в русском языке нет.',ex:'прочитает, будет читать; ошибка: «прочитающий», «сделающий»',cat:'Морфология',f:'будущ[а-яё]* врем(?:я|ени|енем)',at:'pr2',ch:'glag',see:['nast','prosh','vremya']},
 bukva:{t:'Буква',d:'Знак, которым звук обозначается на письме. Звуки мы слышим и произносим, а буквы видим и пишем; их число в слове может не совпадать.',ex:'юный — 4 буквы, 5 звуков',cat:'Общие понятия',f:'букв(?:а|ы|е|у|ой|ам|ами|ах)?',at:'zv1',ch:'zvuki',base:1,see:['zvuk','glasn','orfogr']},
 vid:{t:'Вид глагола',d:'Признак глагола, который показывает, доведено ли действие до конца. Вид бывает совершенный и несовершенный.',ex:'читать (что делать?) — прочитать (что сделать?)',cat:'Морфология',f:'вид(?:а|у|ом|е)? глагол[а-яё]*',at:'pr1',ch:'glag',see:['sov','nesov','glag']},
 vozvr:{t:'Возвратность',d:'Признак глагола и причастия, выраженный постфиксом -ся (-сь). В причастиях -ся не сокращается до -сь даже после гласной.',ex:'строящийся, умывшийся, строящаяся',cat:'Морфология',f:'возвратн[а-яё]*',at:'pr1',ch:'glag',see:['postf','neperekh']},
 vremya:{t:'Время глагола',d:'Признак глагола, который показывает, когда совершается действие по отношению к моменту речи. У причастий есть только настоящее и прошедшее время.',ex:'читающий (настоящее), читавший (прошедшее)',cat:'Морфология',f:'врем(?:я|ени) глагол[а-яё]*',at:'dr1',ch:'glag',see:['nast','prosh','bud']},
 glavslovo:{t:'Главное слово',d:'Слово в словосочетании, от которого задают вопрос к зависимому слову.',ex:'читающий (что?) книгу: «читающий» — главное слово, «книгу» — зависимое',cat:'Синтаксис и пунктуация',f:'главн(?:ое|ого|ому|ым) слов(?:о|а|у|ом)',at:'su0',ch:'slovosoch',see:['dep','slovosoch']},
 glag:{t:'Глагол',d:'Самостоятельная часть речи, которая обозначает действие или состояние и отвечает на вопросы «что делать? что сделать?».',ex:'читать, прочитать, строить, спать',cat:'Морфология',f:'глагол(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'sc1',ch:'glag',see:['vid','vremya','sprya','prich']},
 gl_iskl:{t:'Глаголы-исключения',d:'Глаголы, которые нарушают общее правило определения спряжения: гнать, держать, дышать, слышать, смотреть, видеть, ненавидеть, обидеть, терпеть, вертеть, зависеть относятся ко II спряжению, а брить, стелить — к I, хотя оканчиваются на -ить.',ex:'гонят → гонящий, гонимый; видят → видимый',cat:'Морфология',f:'глагол[а-яё]*-исключени[а-яё]*|(?:одиннадцать|11) исключени[а-яё]*',at:'pr4',ch:'glag',see:['sprya','iskl','infin']},
 glasn:{t:'Гласный звук',d:'Звук, который произносится голосом, свободно, без преград во рту; его можно тянуть и петь. Гласных звуков в русском языке шесть: [а], [о], [у], [ы], [э], [и]; гласных букв десять: а, о, у, ы, э, я, ё, ю, е, и.',ex:'в слове мак один гласный — [а]; в слове луна два гласных — [у] и [а]',cat:'Общие понятия',f:'гласн(?:ый|ая|ое|ые|ого|ой|ому|ую|ым|ыми|ых|ом)',at:'zv1',ch:'zvuki',see:['soglasn','bezud','udar']},
 gram_priznak:{t:'Грамматический признак',d:'Свойство слова, которое выражается его формой: род, число, падеж, вид, время, залог и другие. Признаки бывают постоянными и непостоянными.',ex:'прочитанная: страдательное, прошедшего времени, совершенного вида, ж. р., ед. ч., И. п.',cat:'Морфология',f:'признак(?:и|ов|ам|ами|ах) (?:глагол|прилагательн)[а-яё]*',at:'pr1',ch:'prichastie',see:['chast_rechi','morf_razb','forma']},
 deepr:{t:'Деепричастие',d:'Особая неизменяемая форма глагола, которая обозначает добавочное действие и отвечает на вопросы «что делая? что сделав?».',ex:'читая, прочитав, улыбаясь',cat:'Морфология',f:'деепричасти[а-яё]*',at:'pr1',ch:'deeprich',see:['prich','glag','obst']},
 dejst:{t:'Действительное причастие',d:'Причастие, которое называет признак предмета, совершающего действие сам.',ex:'читающий ученик (ученик читает), распустившийся цветок',cat:'Морфология',f:'действительн(?:ый|ая|ое|ые|ого|ой|ому|ую|ым|ыми|ых|ом)',at:'pr2',ch:'prichastie',see:['strad','zalog','prich']},
 defis:{t:'Дефис',d:'Короткая чёрточка внутри слова или между частями сочетания. Через дефис пишутся, например, повторы.',ex:'глаженые-переглаженые, стираное-перестираное',cat:'Орфография',f:'дефис[а-яё]*',at:'pl6',ch:'slitno',see:['povtor','slitno','razdelno']},
 dobav:{t:'Добавочное значение',d:'Дополнительный оттенок смысла у причастного оборота: причина («так как») или уступка («хотя»). С таким значением оборот перед определяемым словом тоже может обособляться.',ex:'Утомлённые долгой дорогой, путники быстро уснули (= так как были утомлены).',cat:'Синтаксис и пунктуация',f:'добавочн[а-яё]* значени[а-яё]*',at:'',ch:'obos',see:['obosob','prich_ob']},
 dop:{t:'Дополнение',d:'Второстепенный член предложения, который обозначает предмет и отвечает на вопросы косвенных падежей: «кого? чего? кому? чем? о чём?».',ex:'решена (кем?) учеником; уверены (в чём?) в победе',cat:'Синтаксис и пунктуация',f:'дополнени[а-яё]*',at:'pr1',ch:'vtor',see:['chlen','upravl','padezh']},
 dep:{t:'Зависимое слово',d:'Слово, которое подчиняется другому слову и отвечает на вопрос, заданный от него. Если у причастия есть зависимое слово, пишется нн, а не — раздельно.',ex:'жаренная (на чём?) на масле картошка; не прочитанная (кем?) мною книга',cat:'Синтаксис и пунктуация',f:'зависим(?:ое|ого|ому|ым|ом|ые|ых|ыми) слов[а-яё]*|слов[а-яё]*-помощник[а-яё]*',at:'su0',ch:'slovosoch',see:['glavslovo','slovosoch','prich_ob']},
 zalog:{t:'Залог',d:'Признак глагола и причастия, который показывает, сам ли предмет совершает действие или действие направлено на него. Причастия бывают действительного и страдательного залога.',ex:'читающий ученик — читаемая книга',cat:'Морфология',f:'залог(?:а|у|ом|е|и|ов)?',at:'pr1',ch:'prichastie',see:['dejst','strad','prich']},
 zapyat:{t:'Запятая',d:'Знак препинания, который разделяет или выделяет части предложения. Причастный оборот после определяемого слова выделяется запятыми с двух сторон.',ex:'Листья, опавшие за ночь, лежали на дорожке.',cat:'Синтаксис и пунктуация',f:'запят(?:ая|ой|ую|ые|ых|ыми|ым)',at:'pr7',ch:'prostoe',base:1,see:['znaki','obosob']},
 zvuk:{t:'Звук',d:'Самая маленькая единица звучащей речи. Звуки бывают гласные и согласные.',ex:'гласные [а], [о]; согласные [н], [ш]',cat:'Общие понятия',f:'звук(?:а|у|ом|е|и|ов|ам|ами|ах)?',at:'zv1',ch:'zvuki',see:['bukva','glasn','soglasn']},
 znaki:{t:'Знаки препинания',d:'Знаки, которые делят письменную речь на предложения и их части: точка, запятая, тире, двоеточие и другие.',ex:'. , — : ; ! ?',cat:'Синтаксис и пунктуация',f:'знак[а-яё]* препинани[а-яё]*',at:'',ch:'prostoe',base:1,see:['zapyat','punkt']},
 infin:{t:'Инфинитив',d:'Начальная (неопределённая) форма глагола. Отвечает на вопросы «что делать? что сделать?» и оканчивается на -ть, -ти, -чь.',ex:'читать, нести, беречь',cat:'Морфология',f:'инфинитив[а-яё]*|неопредел[её]нн[а-яё]* форм[а-яё]*',at:'sc1',ch:'glag',see:['osn_inf','glag','sprya']},
 iskl:{t:'Исключение',d:'Слово, которое пишется не по общему правилу. Исключения запоминают списком.',ex:'стеклянный, оловянный, деревянный; ветреный; движимый',cat:'Орфография',f:'исключени[а-яё]*',at:'kr4',ch:'koren',base:1,see:['orfogr','gl_iskl']},
 koren:{t:'Корень',d:'Главная часть слова; в ней заключено общее значение родственных слов.',ex:'лес, лес-ной, лес-ник; кож-а, кож-аный',cat:'Морфемика и словообразование',f:'корень|корн(?:я|ю|ем|е|и|ей|ям|ями|ях)',at:'pz1',ch:'sostav',see:['odnokor','morfema','suff']},
 krat:{t:'Краткая форма',d:'Укороченная форма прилагательного или страдательного причастия. Не изменяется по падежам и обычно бывает сказуемым.',ex:'длинный → длинен, длинна; прочитанный → прочитан, прочитана',cat:'Морфология',f:'кратк[а-яё]* форм[а-яё]*',at:'pl3',ch:'pril',see:['poln','krprich','krpril']},
 krpril:{t:'Краткое прилагательное',d:'Краткая форма прилагательного. Называет качество, отвечает на вопрос «каков?», к нему подходит слово «очень». Пишется с тем же числом н, что и полная форма.',ex:'девушка воспитанна (воспитанная), дорога длинна',cat:'Морфология',f:'кратк[а-яё]* прилагательн[а-яё]*',at:'pl3',ch:'pril',see:['krat','krprich','pril']},
 krprich:{t:'Краткое причастие',d:'Краткая форма страдательного причастия. Изменяется по родам и числам, в предложении — сказуемое, пишется с одной н.',ex:'книга прочитана, задача решена (кем?) учеником',cat:'Морфология',f:'кратк[а-яё]* причасти[а-яё]*',at:'pl1',ch:'prichastie',see:['krat','strad','skaz']},
 znach:{t:'Лексическое значение',d:'Смысл слова — то, что оно обозначает: предмет, признак, действие, явление. Значение объясняют толкованием и проверяют по толковому словарю.',ex:'сугроб — куча снега, наметённая ветром; отважный — смелый, храбрый',cat:'Лексика',f:'лексическ[а-яё]* значени[а-яё]*',at:'lk1',ch:'leks',see:['tolkov','tolk_sl','mnogozn']},
 lityaz:{t:'Литературный язык',d:'Образцовая форма языка с едиными для всех нормами. На нём пишут книги и газеты, говорят на уроках и в официальной обстановке.',ex:'язык книг и газет, радио и телевидения, речь учителя на уроке',cat:'Общие понятия',f:'литературн[а-яё]* язык[а-яё]*',at:'pz1',ch:'normy',see:['norma','razgovor']},
 litso:{t:'Лицо',d:'Признак глагола и личного местоимения, который показывает, кто совершает действие: говорящий (1-е лицо), собеседник (2-е) или тот, о ком говорят (3-е).',ex:'я читаю, ты читаешь, они читают',cat:'Морфология',f:'[123]-(?:е|го|м) лиц(?:о|а|у|ом|е)',at:'pr3',ch:'glag',see:['osn_nast','lichmest','chislo']},
 lichmest:{t:'Личное местоимение',d:'Местоимение, которое указывает на участника речи или на того, о ком говорят: я, ты, он, она, оно, мы, вы, они. Причастный оборот при личном местоимении выделяется запятыми всегда.',ex:'Мы, уставшие после похода, легли спать.',cat:'Морфология',f:'личн[а-яё]* местоимени[а-яё]*',at:'pr7',ch:'mest',see:['mest','obosob','litso']},
 mest:{t:'Местоимение',d:'Самостоятельная часть речи, которая указывает на предмет, признак или количество, но не называет их.',ex:'я, мы, он, кто, какой, этот, мой',cat:'Морфология',f:'местоимени[а-яё]*',at:'su0',ch:'mest',see:['lichmest','chast_rechi']},
 morfema:{t:'Морфема',d:'Самая маленькая значимая часть слова: приставка, корень, суффикс, окончание, постфикс.',ex:'за-жар-енн-ый',cat:'Морфемика и словообразование',f:'морфем(?:а|ы|е|у|ой|ам|ами|ах)?',at:'sc1',ch:'sostav',see:['koren','pref','suff','okonch']},
 morfemika:{t:'Морфемика',d:'Раздел науки о языке, который изучает состав слова: корни, приставки, суффиксы, окончания.',ex:'разбор по составу: за-жар-енн-ый',cat:'Общие понятия',f:'морфемик(?:а|и|е|у|ой)',at:'sc1',ch:'sostav',see:['morfema','morf_sostav','slovoobr']},
 morf_razb:{t:'Морфологический разбор',d:'Описание слова как части речи: его начальная форма, постоянные и непостоянные признаки и роль в предложении.',ex:'прочитанная — причастие, от глагола прочитать; страдательное, прошедшего времени…',cat:'Морфология',f:'морфологическ[а-яё]* разбор[а-яё]*',at:'su4',ch:'sush',see:['gram_priznak','chast_rechi']},
 morfologia:{t:'Морфология',d:'Раздел науки о языке, который изучает части речи и формы слов.',ex:'причастие, его разряды и склонение',cat:'Общие понятия',f:'морфологи(?:я|и|ю|ей)',at:'su0',ch:'sush',see:['chast_rechi','morf_razb','morfemika']},
 naklon:{t:'Наклонение',d:'Признак глагола, который показывает, как действие связано с действительностью: происходит на самом деле, желательно или требуется. Наклонения: изъявительное, условное, повелительное.',ex:'читает, читал бы, читай',cat:'Морфология',f:'наклонени[а-яё]*',at:'dr1',ch:'glag',see:['glag','vremya','litso']},
 narech:{t:'Наречие',d:'Неизменяемая самостоятельная часть речи, которая обозначает признак действия или другого признака и отвечает на вопросы «как? где? когда?».',ex:'неожиданно, взволнованно, ветрено',cat:'Морфология',f:'наречи(?:е|я|ю|ем|и|й|ям|ями|ях)',at:'ps1',ch:'narech',see:['obst','pril','krprich']},
 nast:{t:'Настоящее время',d:'Время действия, которое происходит в момент речи. Причастия настоящего времени образуются от основы настоящего времени и только от глаголов несовершенного вида.',ex:'читающий, строящий, читаемый, видимый',cat:'Морфология',f:'настоящ[а-яё]* врем(?:я|ени|енем)',at:'pr2',ch:'glag',see:['prosh','osn_nast','nesov']},
 ne_prich:{t:'Не с причастиями',d:'Правило написания не. Слитно — с полным причастием без зависимых слов; раздельно — при зависимых словах, при противопоставлении с «а» и с краткой формой.',ex:'непрочитанная книга — не прочитанная мною книга — книга не прочитана',cat:'Орфография',f:'не с причасти[а-яё]*',at:'pr6',ch:'ne',see:['slitno','razdelno','chastica','dep']},
 neperekh:{t:'Непереходный глагол',d:'Глагол, при котором не может стоять дополнение в винительном падеже без предлога. Страдательных причастий от него нет.',ex:'спать, идти, кипеть, строиться',cat:'Морфология',f:'непереходн[а-яё]*',at:'pr2',ch:'glag',see:['perekh','vozvr','strad']},
 nesov:{t:'Несовершенный вид',d:'Вид глагола, который называет действие без указания на его завершение и отвечает на вопрос «что делать?». Только от таких глаголов образуются причастия настоящего времени.',ex:'читать → читающий, читаемый',cat:'Морфология',f:'несовершенн[а-яё]* вид(?:а|у|ом|е)?',at:'pr1',ch:'glag',see:['sov','vid','nast']},
 nul:{t:'Нулевое окончание',d:'Окончание, которое не выражено ни звуком, ни буквой, но показывает форму слова.',ex:'лимон, конь, (книга) прочитан',cat:'Морфемика и словообразование',f:'нулев[а-яё]* окончани[а-яё]*',at:'sc2',ch:'sostav',see:['okonch','osnova']},
 obosob:{t:'Обособление',d:'Выделение части предложения запятыми на письме и интонацией в речи. Причастный оборот обособляется, если стоит после определяемого слова или относится к личному местоимению.',ex:'Листья, опавшие за ночь, лежали на дорожке. Уставшие после похода, мы легли спать.',cat:'Синтаксис и пунктуация',f:'обособ[а-яё]*|выделя(?:ется|ются|ться) запят[а-яё]*',at:'pr7',ch:'obos',see:['prich_ob','zapyat','opr_slovo','dobav']},
 obst:{t:'Обстоятельство',d:'Второстепенный член предложения, который показывает, как, где, когда или почему совершается действие. Часто выражается наречием.',ex:'Он отвечал обдуманно. Листья лежали на дорожке.',cat:'Синтаксис и пунктуация',f:'обстоятельств[а-яё]*',at:'pr1',ch:'vtor',see:['narech','chlen','deepr']},
 odnokor:{t:'Однокоренные слова',d:'Слова с одним и тем же корнем и близким значением.',ex:'жарить, жареный, зажаренный, жаркое',cat:'Морфемика и словообразование',f:'однокоренн[а-яё]*',at:'zv1',ch:'sostav',see:['koren','ishod']},
 okonch:{t:'Окончание',d:'Изменяемая часть в конце слова. Окончание меняется, когда меняется форма слова, и связывает слово с другими словами.',ex:'окн-о, окн-а, окн-ом; рек-а, рек-и, рек-у',cat:'Морфемика и словообразование',f:'окончани[а-яё]*',at:'pz1',ch:'sostav',see:['osnova','nul','sklon']},
 opred:{t:'Определение',d:'Второстепенный член предложения, который обозначает признак предмета и отвечает на вопросы «какой? чей?». Полное причастие и причастный оборот в предложении — определение.',ex:'прочитанная книга; листья, опавшие за ночь',cat:'Синтаксис и пунктуация',f:'определени[а-яё]*',at:'pl1',ch:'vtor',see:['opr_slovo','prich_ob','chlen']},
 opr_slovo:{t:'Определяемое слово',d:'Слово, к которому относится определение или причастный оборот. С ним причастие согласуется, и от него задают вопрос «какой?».',ex:'Листья (какие?), опавшие за ночь, … — определяемое слово «листья»',cat:'Синтаксис и пунктуация',f:'определяем(?:ое|ого|ому|ым|ом|ые|ых|ыми)',at:'pr7',ch:'obos',see:['opred','prich_ob','obosob']},
 orfogramma:{t:'Орфограмма',d:'Место в слове, где можно ошибиться и где написание выбирают по правилу.',ex:'безударный гласный в «в_да» (во́ды); парный согласный в «ду_» (дубы́)',cat:'Орфография',f:'орфограмм[а-яё]*',at:'zv5',ch:'koren',see:['orfogr','pravop']},
 orfogr:{t:'Орфография',d:'Система правил написания слов и раздел науки о языке, который эти правила изучает.',ex:'вода — проверка во́ды; дуб — дубы́; жи, ши пишутся с буквой и',cat:'Орфография',f:'орфографи[а-яё]*',at:'lk6',ch:'koren',see:['orfogramma','pravop','punkt']},
 osnova:{t:'Основа',d:'Часть слова без окончания и постфикса. Если основа оканчивается на н, а суффикс тоже начинается с н, получается нн.',ex:'лимон + н → лимонный; чита-ть: основа инфинитива чита-',cat:'Морфемика и словообразование',f:'основ(?:а|ы|е|у|ой|ам|ами|ах)?',at:'sc2',ch:'sostav',see:['osn_nast','osn_inf','okonch','styk']},
 osn_inf:{t:'Основа инфинитива',d:'Часть инфинитива без -ть (-ти). От неё образуются причастия прошедшего времени.',ex:'чита-ть → чита-вший, чита-нный; увиде-ть → увиде-вший',cat:'Морфемика и словообразование',f:'основ[а-яё]* инфинитива',at:'pr3',ch:'glag',see:['osn_nast','prosh','infin']},
 osn_nast:{t:'Основа настоящего времени',d:'Основа глагола, которую легко найти, отбросив окончание в форме «они …». От неё образуются причастия настоящего времени.',ex:'они чита-ют → чита-ющий; они нес-ут → нес-омый',cat:'Морфемика и словообразование',f:'основ[а-яё]* настоящего времени',at:'pr3',ch:'glag',see:['osn_inf','nast','sprya']},
 otgl:{t:'Отглагольное прилагательное',d:'Прилагательное, образованное от глагола. В отличие от причастия, оно называет постоянный признак без действия и пишется с одной н.',ex:'жареная рыба (но: зажаренная на огне — причастие); варёный, кованый',cat:'Морфология',f:'отглагольн[а-яё]*',at:'pr1',ch:'nn',see:['prich','otym','glag']},
 otym:{t:'Отымённое прилагательное',d:'Прилагательное, образованное от существительного. Сколько в нём писать н, зависит от суффикса.',ex:'кожа → кожаный, клюква → клюквенный, лимон → лимонный',cat:'Морфология',f:'отым[её]нн[а-яё]*',at:'nn1',ch:'nn',see:['pril','suff','otgl','sush']},
 padezh:{t:'Падеж',d:'Форма имени, которая показывает его связь с другими словами в предложении. Падежей шесть: именительный, родительный, дательный, винительный, творительный, предложный.',ex:'читающего ученика (Р. п.), читающими детьми (Т. п.)',cat:'Морфология',f:'падеж(?:а|у|ом|е|и|ей|ам|ами|ах)?',at:'su4',ch:'sush',see:['sklon','rod','chislo']},
 perekhod:{t:'Переход в другую часть речи',d:'Случай, когда слово теряет прежние признаки и начинает употребляться как слово другой части речи.',ex:'блестящий ответ (прилагательное); учащиеся, заведующий (существительные)',cat:'Морфология',f:'переход(?:а|ом|е)? в (?:прилагательн|существительн)[а-яё]*',at:'pr1',ch:'slovoobr',see:['prich','pril','sush']},
 perekh:{t:'Переходный глагол',d:'Глагол, который может управлять существительным в винительном падеже без предлога. Только от переходных глаголов образуются страдательные причастия.',ex:'читать (что?) книгу → читаемая книга',cat:'Морфология',f:'переходн[а-яё]*',at:'pr2',ch:'glag',see:['neperekh','strad','upravl']},
 povtor:{t:'Повтор',d:'Сочетание из одного слова, взятого дважды, во второй раз — с приставкой пере-. Обозначает высокую степень качества; обе части пишутся с одной н.',ex:'глаженые-переглаженые брюки, штопаные-перештопаные носки',cat:'Морфемика и словообразование',f:'повтор(?:ы|ах|ов|ами)?',at:'ps1',ch:'nn',see:['defis','otgl','pref']},
 podl:{t:'Подлежащее',d:'Главный член предложения, который называет, о ком или о чём говорится. Отвечает на вопросы «кто?» или «что?».',ex:'Задача решена. Мы легли спать.',cat:'Синтаксис и пунктуация',f:'подлежащ(?:ее|его|ему|им|ем|ие|их|ими)',at:'pr1',ch:'glavn',see:['skaz','chlen','predl']},
 poln:{t:'Полная форма',d:'Основная форма прилагательного или причастия, которая изменяется по родам, числам и падежам и в предложении обычно бывает определением.',ex:'прочитанная книга, длинная дорога',cat:'Морфология',f:'полн[а-яё]* форм[а-яё]*|полн[а-яё]* и кратк[а-яё]* форм[а-яё]*',at:'pl3',ch:'pril',see:['krat','opred','sklon']},
 postf:{t:'Постфикс',d:'Часть слова, которая стоит после окончания. В глаголах и причастиях это -ся (-сь); он делает слово возвратным.',ex:'строящий-ся, умывший-ся',cat:'Морфемика и словообразование',f:'постфикс[а-яё]*',at:'sc4',ch:'sostav',see:['vozvr','suff','okonch']},
 pravop:{t:'Правописание',d:'Написание слов по правилам орфографии; так называют и само правило.',ex:'правописание причастий, правописание н и нн',cat:'Орфография',f:'правописани[а-яё]*',at:'',ch:'koren',base:1,see:['orfogr','orfogramma']},
 predlog:{t:'Предлог',d:'Служебная часть речи, которая связывает существительное или местоимение с другими словами.',ex:'жаренная на масле; о читающем мальчике; с книгой',cat:'Морфология',f:'предлог(?:а|у|ом|е|и|ов|ами|ах)?',at:'kr1',ch:'sluzh',see:['sluzh','padezh','soyuz']},
 predl:{t:'Предложение',d:'Слово или несколько слов, которые выражают законченную мысль. В конце предложения ставится точка, вопросительный или восклицательный знак.',ex:'Книга прочитана. Листья лежали на дорожке.',cat:'Синтаксис и пунктуация',f:'предложени[а-яё]*',at:'',ch:'prostoe',base:1,see:['chlen','podl','skaz']},
 priznak:{t:'Признак предмета',d:'Свойство предмета: цвет, качество, материал, принадлежность. Прилагательное называет постоянный признак, причастие — признак по действию.',ex:'синий (просто цвет) — синеющий (который синеет)',cat:'Морфология',f:'признак[а-яё]* предмет[а-яё]*',at:'sc1',ch:'pril',see:['pril','prich','opred']},
 pril:{t:'Прилагательное',d:'Самостоятельная часть речи, которая обозначает признак предмета и отвечает на вопросы «какой? чей?». Изменяется по родам, числам и падежам.',ex:'кожаный, лимонный, длинный, красивый',cat:'Морфология',f:'прилагательн[а-яё]*',at:'sc1',ch:'pril',see:['otym','otgl','prich','krpril','kach_pril','otn_pril','prit_pril','st_sravn']},
 kach_pril:{t:'Качественное прилагательное',d:'Прилагательное, которое называет признак самого предмета, способный быть больше или меньше. Обычно имеет краткую форму и степени сравнения, сочетается со словом «очень».',ex:'тихий — тих, тише; очень смелый; каменное (неподвижное) лицо',cat:'Морфология',f:'качественн[а-яё]* прилагательн[а-яё]*',at:'pl2',ch:'pril',see:['pril','otn_pril','prit_pril','krpril','st_sravn']},
 otn_pril:{t:'Относительное прилагательное',d:'Прилагательное, которое называет признак через отношение к другому предмету, месту, времени или действию: материал, место, время, назначение. Не имеет краткой формы и степеней сравнения.',ex:'деревянная ложка (из дерева), лесная тропа (в лесу), вчерашний разговор',cat:'Морфология',f:'относительн[а-яё]* прилагательн[а-яё]*',at:'pl2',ch:'pril',see:['pril','kach_pril','prit_pril']},
 prit_pril:{t:'Притяжательное прилагательное',d:'Прилагательное, которое обозначает принадлежность человеку или животному и отвечает на вопрос «чей?». Суффиксы -ин- (-ын-), -ов- (-ев-), -ий-.',ex:'мамин шарф, отцов портфель, лисий хвост — лисья нора, лисьего',cat:'Морфология',f:'притяжательн[а-яё]* прилагательн[а-яё]*',at:'pl2',ch:'pril',see:['pril','kach_pril','otn_pril']},
 st_sravn:{t:'Степени сравнения',d:'Формы качественного прилагательного, которые показывают, что признак у предмета больше (меньше), чем у другого (сравнительная степень) или чем у всех (превосходная степень). У каждой степени есть простая и составная форма.',ex:'высокий — выше, более высокий — высочайший, самый высокий, выше всех',cat:'Морфология',f:'степен(?:ь|и|ей|ям|ями|ях) сравнени[а-яё]*',at:'pl4',ch:'pril',see:['sravn_st','prev_st','kach_pril']},
 sravn_st:{t:'Сравнительная степень',d:'Форма качественного прилагательного, которая показывает, что признак в одном предмете больше (или меньше), чем в другом. Простая форма — суффиксы -ее (-ей), -е, -ше; составная — слова «более», «менее» + прилагательное.',ex:'добрее, громче, тоньше, лучше; более тёплый, менее трудный',cat:'Морфология',f:'сравнительн[а-яё]* степен[а-яё]*',at:'pl4',ch:'pril',see:['st_sravn','prev_st']},
 prev_st:{t:'Превосходная степень',d:'Форма качественного прилагательного, которая показывает, что признак у предмета больше (или меньше), чем у всех других. Простая форма — суффиксы -ейш-, -айш-; составная — «самый», «наиболее», «наименее» + прилагательное или сравнительная степень + «всех», «всего».',ex:'добрейший, высочайший; самый высокий, наиболее удобный, сильнее всех',cat:'Морфология',f:'превосходн[а-яё]* степен[а-яё]*',at:'pl4',ch:'pril',see:['st_sravn','sravn_st']},
 nach_f:{t:'Начальная форма прилагательного',d:'Форма, в которой прилагательное записано в словаре: именительный падеж единственного числа мужского рода.',ex:'(о) тёплой (погоде) → тёплый; лисьи → лисий; маминой → мамин',cat:'Морфология',f:'начальн[а-яё]* форм[а-яё]* прилагательн[а-яё]*',at:'pl1',ch:'pril',see:['pril','morf_razb']},
 pref:{t:'Приставка',d:'Значимая часть слова, которая стоит перед корнем и служит для образования новых слов: бежать — при-бежать, писать — пере-писать. Пишется слитно.',ex:'с-жать, раз-жать, под-ъезд, рас-сказ, при-морский',cat:'Морфемика и словообразование',f:'приставк[а-яё]*|приставочн[а-яё]*',at:'pz1',ch:'sostav',see:['koren','suff','otgl']},
 prich:{t:'Причастие',d:'Особая форма глагола, которая обозначает признак предмета по действию и отвечает на вопросы «какой? что делающий? что сделавший?». Сочетает признаки глагола и прилагательного.',ex:'бегущий ручей (который бежит), прочитанная книга (которую прочитали)',cat:'Морфология',f:'причасти[а-яё]*',at:'pl1',ch:'prichastie',see:['deepr','pril','glag','prich_ob']},
 prich_ob:{t:'Причастный оборот',d:'Причастие вместе с зависимыми словами. В предложении весь оборот — одно определение.',ex:'дети, игравшие во дворе; опавшие за ночь листья',cat:'Синтаксис и пунктуация',f:'причастн[а-яё]* оборот[а-яё]*',at:'pr7',ch:'prichastie',see:['prich','dep','obosob','opr_slovo']},
 proizv:{t:'Производное слово',d:'Слово, образованное от другого слова с помощью приставки, суффикса или иным способом.',ex:'кожаный (от «кожа»), воспитанник (от «воспитанный»)',cat:'Морфемика и словообразование',f:'производн[а-яё]* слов[а-яё]*',at:'sc6',ch:'slovoobr',see:['ishod','slovoobr']},
 ishod:{t:'Производящее слово',d:'Слово, от которого образовано другое слово; его называют также исходным. С него начинается проверка н и нн.',ex:'кожа → кожаный; неожиданный → неожиданно; гостиный → гостиная',cat:'Морфемика и словообразование',f:'исходн[а-яё]* слов[а-яё]*|производящ[а-яё]* слов[а-яё]*',at:'sc6',ch:'slovoobr',see:['proizv','slovoobr','odnokor']},
 protivop:{t:'Противопоставление',d:'Сочетание, в котором одно отрицается, а другое утверждается, обычно с союзом «а». При противопоставлении не с причастием пишется раздельно.',ex:'не прочитанная, а пролистанная книга',cat:'Синтаксис и пунктуация',f:'противопоставлени[а-яё]*',at:'pr6',ch:'ne',see:['ne_prich','soyuz','razdelno']},
 prosh:{t:'Прошедшее время',d:'Время действия, которое было до момента речи. Причастия прошедшего времени образуются от основы инфинитива.',ex:'читавший, нёсший, прочитанный, взятый',cat:'Морфология',f:'прошедш[а-яё]* врем(?:я|ени|енем)',at:'su0',ch:'glag',see:['nast','osn_inf','bud']},
 punkt:{t:'Пунктуация',d:'Правила расстановки знаков препинания, а также раздел науки о языке, который их изучает.',ex:'запятые при причастном обороте',cat:'Синтаксис и пунктуация',f:'пунктуаци[а-яё]*',at:'dr1',ch:'prostoe',see:['znaki','zapyat','sintaksis']},
 morf_sostav:{t:'Разбор по составу',d:'Выделение в слове всех его частей: приставки, корня, суффикса, окончания, постфикса.',ex:'за-жар-енн-ый, вы-мыт-ый, строя-щ-ий-ся',cat:'Морфемика и словообразование',f:'разбор[а-яё]* (?:слова )?по составу|морфемн[а-яё]* разбор[а-яё]*',at:'sc6',ch:'sostav',see:['morfema','koren','suff']},
 razgovor:{t:'Разговорная форма',d:'Форма слова, привычная в непринуждённой устной речи, но не соответствующая строгой литературной норме.',ex:'мерять, мучать (литературные: мерить, мучить)',cat:'Общие понятия',f:'разговорн[а-яё]*',at:'pz1',ch:'stili',see:['norma','lityaz']},
 razdelno:{t:'Раздельное написание',d:'Написание слов отдельно друг от друга, через пробел.',ex:'не прочитанная мною книга; книга не прочитана',cat:'Орфография',f:'раздельн(?:о|ое|ого|ому|ым|ом)',at:'ps1',ch:'slitno',see:['slitno','defis','ne_prich']},
 razryad:{t:'Разряд',d:'Группа слов одной части речи, объединённых общим признаком. Причастия делятся на четыре разряда по залогу и времени.',ex:'действительные настоящего времени: читающий; страдательные прошедшего: прочитанный',cat:'Морфология',f:'разряд(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'pl2',ch:'pril',see:['zalog','vremya','dejst','strad']},
 rod:{t:'Род',d:'Признак, по которому слова делятся на мужской, женский и средний род. У существительного род постоянный, а прилагательное и причастие меняют род вслед за существительным.',ex:'читающий мальчик, читающая девочка, читающее дитя',cat:'Морфология',f:'(?:мужск|женск|средн)[а-яё]* род(?:а|у|ом|е)?',at:'su2',ch:'sush',see:['chislo','padezh','soglas']},
 samost:{t:'Самостоятельная часть речи',d:'Часть речи, слова которой называют предметы, признаки, действия или количество и бывают членами предложения.',ex:'существительное, прилагательное, глагол, наречие',cat:'Морфология',f:'самостоятельн[а-яё]* част[а-яё]* речи',at:'su0',ch:'sush',see:['chast_rechi','sluzh']},
 sintaksis:{t:'Синтаксис',d:'Раздел науки о языке, который изучает словосочетания и предложения.',ex:'причастный оборот и запятые при нём',cat:'Общие понятия',f:'синтаксис[а-яё]*',at:'',ch:'prostoe',see:['predl','slovosoch','punkt']},
 skaz:{t:'Сказуемое',d:'Главный член предложения, который сообщает, что делает подлежащее, каково оно или что с ним происходит. Краткое причастие в предложении — сказуемое.',ex:'Задача решена. Дорога длинна. Ученики собрались.',cat:'Синтаксис и пунктуация',f:'сказуем[а-яё]*',at:'pl1',ch:'glavn',see:['podl','krprich','chlen']},
 sklon:{t:'Склонение',d:'Изменение слова по падежам и числам. Полное причастие склоняется так же, как прилагательное.',ex:'читающий, читающего, читающему, о читающем',cat:'Морфология',f:'склонени[а-яё]*|склоня(?:ется|ются)',at:'su4',ch:'sush',see:['padezh','okonch','poln']},
 slitno:{t:'Слитное написание',d:'Написание частей слова вместе, без пробела и дефиса.',ex:'непрочитанная книга, незваный, ненавидящий',cat:'Орфография',f:'слитн(?:о|ое|ого|ому|ым|ом)',at:'ps1',ch:'slitno',see:['razdelno','defis','ne_prich']},
 slovoobr:{t:'Словообразование',d:'Образование новых слов от уже существующих, а также раздел науки о языке, который это изучает.',ex:'дружина → дружинник; жарить → жареный',cat:'Морфемика и словообразование',f:'словообразовани[а-яё]*|словообразовательн[а-яё]*',at:'sc1',ch:'slovoobr',see:['ishod','proizv','morfema']},
 slovosoch:{t:'Словосочетание',d:'Два или больше самостоятельных слова, связанных по смыслу и грамматически: одно из них главное, другое зависимое.',ex:'читаемая книга, мощённая булыжником, любующийся закатом',cat:'Синтаксис и пунктуация',f:'словосочетани[а-яё]*',at:'lk1',ch:'slovosoch',see:['glavslovo','dep','soglas','upravl']},
 slozhn:{t:'Сложное слово',d:'Слово, в котором два корня или больше.',ex:'гладкокрашеный, домотканый, свежемороженый',cat:'Морфемика и словообразование',f:'сложн(?:ое|ого|ому|ым|ом|ые|ых|ыми) слов[а-яё]*',at:'sc5',ch:'slovoobr',see:['koren','slozhnosokr']},
 slozhnosokr:{t:'Сложносокращённое слово',d:'Слово, составленное из сокращённых частей нескольких слов.',ex:'юннат (юный натуралист), вуз, спецкор',cat:'Морфемика и словообразование',f:'сложносокращ[её]нн[а-яё]*',at:'sg4',ch:'slovoobr',see:['slozhn','styk']},
 sluzh:{t:'Служебная часть речи',d:'Часть речи, слова которой ничего не называют и не бывают членами предложения: они связывают слова или добавляют оттенки смысла.',ex:'предлоги, союзы, частицы',cat:'Морфология',f:'служебн[а-яё]* част[а-яё]* речи',at:'su0',ch:'sush',see:['chast_rechi','predlog','soyuz','chastica']},
 sov:{t:'Совершенный вид',d:'Вид глагола, который обозначает законченное действие или его результат и отвечает на вопрос «что сделать?». Причастие от глагола совершенного вида пишется с нн даже без приставки.',ex:'бросить → брошенный, решить → решённый, купить → купленный',cat:'Морфология',f:'совершенн[а-яё]* вид(?:а|у|ом|е)?',at:'pr1',ch:'glag',see:['nesov','vid','prich']},
 soglasn:{t:'Согласный звук',d:'Звук, при произнесении которого воздух встречает во рту преграду: губы, зубы или язык. В согласном есть шум — только шум или шум вместе с голосом.',ex:'[п], [с], [ш], [б], [з]; в слове кот два согласных — [к] и [т]',cat:'Общие понятия',f:'согласн(?:ый|ая|ое|ые|ого|ой|ому|ую|ым|ыми|ых|ом)',at:'zv1',ch:'zvuki',see:['glasn','shipyash','zvuk']},
 soglas:{t:'Согласование',d:'Связь, при которой зависимое слово ставится в том же роде, числе и падеже, что и главное. Так причастие и прилагательное связаны с существительным.',ex:'читающего ученика, читающей девочке, читающими детьми',cat:'Синтаксис и пунктуация',f:'согласовани[а-яё]*|согласу(?:ется|ются|ющ[а-яё]*)',at:'pl1',ch:'slovosoch',see:['upravl','rod','chislo','padezh']},
 soyuz:{t:'Союз',d:'Служебная часть речи, которая связывает однородные члены предложения или части сложного предложения.',ex:'и, а, но, потому что; не прочитанная, а пролистанная',cat:'Морфология',f:'союз(?:а|у|ом|е|ы|ов|ами|ах)?',at:'su0',ch:'sluzh',see:['sluzh','protivop','chastica']},
 sprya:{t:'Спряжение',d:'Изменение глагола по лицам и числам; так же называют две группы глаголов — I и II спряжение — с разными личными окончаниями. От спряжения зависит гласная в суффиксе причастия настоящего времени.',ex:'I: колеблют → колеблющий; II: клеят → клеящий, видят → видимый',cat:'Морфология',f:'спряжени[а-яё]*',at:'pr4',ch:'glag',see:['gl_iskl','osn_nast','litso','okonch']},
 strad:{t:'Страдательное причастие',d:'Причастие, которое называет признак предмета, на который направлено чужое действие. Образуется только от переходных глаголов.',ex:'читаемая учеником книга, построенный дом',cat:'Морфология',f:'страдательн[а-яё]*',at:'pr2',ch:'prichastie',see:['dejst','zalog','perekh','krprich']},
 styk:{t:'Стык морфем',d:'Место, где встречаются две части слова, например приставка и корень. На стыке звуки влияют друг на друга: в слове с|жать звучит долгий [жж]. На стыке может оказаться и двойная буква: рас|сказ.',ex:'с|жать [жжа́т\'], раз|жать, бес|шумный [б\'ишшу́мный\'], рас|сказ',cat:'Морфемика и словообразование',f:'стык(?:а|е|ом|и|ах)?',at:'pz1',ch:'sostav',see:['osnova','suff','morfema']},
 suff:{t:'Суффикс',d:'Часть слова после корня, которая служит для образования новых слов или форм.',ex:'камен-н-ый, камен-ист-ый, дом-ик',cat:'Морфемика и словообразование',f:'суффикс[а-яё]*',at:'om1',ch:'sostav',see:['pref','koren','suff_prich']},
 suff_prich:{t:'Суффиксы причастий',d:'Суффиксы, с помощью которых причастия образуются от глагола: -ущ-/-ющ-, -ащ-/-ящ-, -ем-/-ом-, -им-, -вш-, -ш-, -нн-, -енн-, -т-.',ex:'несущий, видимый, читавший, нёсший, прочитанный, взятый',cat:'Морфемика и словообразование',f:'суффикс[а-яё]* причасти[а-яё]*',at:'pr3',ch:'prichastie',see:['suff','sprya','osn_nast','osn_inf']},
 sush:{t:'Существительное',d:'Самостоятельная часть речи, которая обозначает предмет и отвечает на вопросы «кто? что?». Имеет род, изменяется по числам и падежам.',ex:'кожа, лимон, дружинник, мороженое',cat:'Морфология',f:'существительн[а-яё]*',at:'sc1',ch:'sush',see:['pril','rod','padezh']},
 sobstv:{t:'Собственное существительное',d:'Имя или название отдельного, единичного предмета: имя, фамилия, кличка, название города, реки, книги. Пишется с прописной буквы; названия книг, газет, кораблей — ещё и в кавычках.',ex:'Анна, Москва, Волга, кот Пушок, роман «Война и мир»',cat:'Морфология',f:'собственн[а-яё]* (?:существительн|им(?:я|ена|ён))[а-яё]*',at:'su1',ch:'sush',see:['naric','sush']},
 naric:{t:'Нарицательное существительное',d:'Общее название однородных предметов, явлений, действий, качеств. Пишется со строчной буквы.',ex:'город, река, девочка, кот, смелость',cat:'Морфология',f:'нарицательн[а-яё]*',at:'su1',ch:'sush',see:['sobstv','sush']},
 odush:{t:'Одушевлённые и неодушевлённые существительные',d:'Одушевлённые называют людей и животных и отвечают на вопрос «кто?»; неодушевлённые — всё остальное (в том числе растения и множества: народ, стадо) и отвечают на вопрос «что?». У одушевлённых винительный падеж множественного числа совпадает с родительным: вижу коней — нет коней.',ex:'кто? брат, пчела; что? дуб, стадо, ветер',cat:'Морфология',f:'(?:не)?одушевл[её]нн[а-яё]*',at:'su1',ch:'sush',see:['sush','padezh']},
 konkr:{t:'Конкретные и отвлечённые существительные',d:'Конкретные называют предметы, которые можно посчитать по одному (стол — два стола); отвлечённые — качества, чувства, состояния, действия (смелость, радость, бег). Деление проводится только у нарицательных существительных.',ex:'конкретные: ручей, книга; отвлечённые: доброта, тишина',cat:'Морфология',f:'отвлеч[её]нн[а-яё]* существительн[а-яё]*|конкретн[а-яё]* и отвлеч[её]нн[а-яё]*',at:'su1',ch:'sush',see:['sobir','sush']},
 sobir:{t:'Собирательные существительные',d:'Существительные, которые называют множество одинаковых предметов или живых существ как одно целое. Имеют только единственное число и не сочетаются с числами «два, три…».',ex:'листва, детвора, молодёжь, мебель, бельё',cat:'Морфология',f:'собирательн[а-яё]*',at:'su1',ch:'sush',see:['konkr','chislo']},
 obsh_rod:{t:'Общий род',d:'Род существительных на -а, -я, которые называют человека по черте характера и могут относиться и к мужчине, и к женщине: такой неряха — такая неряха.',ex:'сирота, неряха, плакса, умница, задира, соня, коллега',cat:'Морфология',f:'общ(?:его|ий|ему|им|ем) род[а-яё]*',at:'su2',ch:'sush',see:['rod','sush']},
 raznoskl:{t:'Разносклоняемые существительные',d:'Существительные, которые в одних падежах изменяются как 3-е склонение (Р., Д., П. п. на -и), а в других — как 2-е (Т. п. на -ем, -ём). Это десять слов на -мя (время, имя, знамя, пламя, племя, семя, стремя, темя, вымя, бремя) и слово «путь».',ex:'о времени, знаменем, на пути, путём',cat:'Морфология',f:'разносклоняем[а-яё]*',at:'su4',ch:'sush',see:['sklon','neskl']},
 neskl:{t:'Несклоняемые существительные',d:'Существительные, которые не изменяются ни по падежам, ни по числам; падеж и число видны только по соседним словам. Род неодушевлённых несклоняемых — обычно средний, у названий людей — по полу, у названий животных — мужской, у городов и рек — по родовому слову.',ex:'новое пальто, в метро, маленький пони, пожилая леди, солнечный Сочи',cat:'Морфология',f:'несклоняем[а-яё]*',at:'su2',ch:'sush',see:['sklon','raznoskl','rod']},
 udar:{t:'Ударение',d:'Выделение одного слога в слове силой и длительностью голоса: ударный гласный звучит дольше и чётче остальных. В русском языке ударение может стоять на любом слоге и переходить с одного слога на другой в формах одного слова.',ex:'доро́га, ма́ма; вода́ — во́ды; за́мок — замо́к',cat:'Общие понятия',f:'ударени[а-яё]*|ударн(?:ый|ая|ое|ые|ого|ой|ом|ых|ым)',at:'zv1',ch:'udar',see:['bezud','glasn','slog']},
 upravl:{t:'Управление',d:'Связь, при которой главное слово требует, чтобы зависимое стояло в определённом падеже. Причастие управляет так же, как глагол, от которого оно образовано.',ex:'читающий (что?) книгу; любующийся (чем?) закатом',cat:'Синтаксис и пунктуация',f:'управлени[а-яё]*',at:'pl1',ch:'slovosoch',see:['soglas','perekh','padezh']},
 ustar:{t:'Устаревшее слово',d:'Слово, которое вышло из живого употребления: исчез предмет (историзм) или его стали называть иначе (архаизм). У архаизмов в словаре стоит помета «устар.»; историзм узнают по толкованию («старинный», «в старину»).',ex:'кафтан, ямщик — историзмы; очи (глаза), чело (лоб) — архаизмы',cat:'Лексика',f:'устаревш[а-яё]*',at:'lk4',ch:'leks',see:['istorizm','arhaizm','pometa']},
 ustoich:{t:'Устойчивое сочетание',d:'Сочетание слов, которое не составляют каждый раз заново, а берут из языка готовым, целиком. Если его смысл не складывается из значений слов, это фразеологизм.',ex:'железная дорога, принять решение; бить баклуши (бездельничать) — фразеологизм',cat:'Лексика',f:'устойчив[а-яё]* сочетани[а-яё]*',at:'lk1',ch:'fraz',see:['frazeol','znach']},
 forma:{t:'Форма слова',d:'Вариант одного и того же слова, который отличается окончанием (иногда суффиксом) и выражает грамматическое значение.',ex:'читающий, читающего, читающими — формы одного причастия',cat:'Морфология',f:'форм[а-яё]* слов(?:а|о)',at:'lk1',ch:'sostav',see:['okonch','sklon','gram_priznak']},
 chastica:{t:'Частица',d:'Служебная часть речи, которая добавляет слову или предложению оттенок значения: отрицание, вопрос, усиление. Не — отрицательная частица.',ex:'книга не прочитана; вовсе не интересующийся',cat:'Морфология',f:'частиц(?:а|ы|е|у|ей|ами|ам|ах)?',at:'su0',ch:'sluzh',see:['sluzh','ne_prich','soyuz']},
 chast_rechi:{t:'Часть речи',d:'Большая группа слов с общим значением, общими вопросами и грамматическими признаками. Части речи бывают самостоятельные и служебные.',ex:'существительное, прилагательное, глагол, наречие; предлог, союз, частица',cat:'Морфология',f:'част(?:ь|и|ей|ям|ями|ях) речи',at:'lk1',ch:'sush',see:['samost','sluzh','gram_priznak']},
 cheredov:{t:'Чередование',d:'Замена одного звука другим в одной и той же части слова в разных словах или формах.',ex:'бросить — брошенный (с/ш), купить — купленный (п/пл)',cat:'Морфемика и словообразование',f:'чередовани[а-яё]*',at:'sc3',ch:'sostav',see:['koren','osnova']},
 sc_formoobr:{t:'Формообразующий суффикс',d:'Суффикс, который образует форму того же слова, а не новое слово. На первом уровне это -ть, -ти (читать, нести) и -л- (читал, читала).',ex:'чита-ть, чита-л, нес-ти',cat:'Морфемика и словообразование',f:'формообразующ[а-яё]* суффикс[а-яё]*',at:'sc2',ch:'sostav',see:['suff','okonch','forma']},
 sc_slovoobr_morf:{t:'Словообразующие морфемы',d:'Приставка и суффикс, с помощью которых из одного слова образуется другое.',ex:'лес → лес-ник, писать → пере-писать',cat:'Морфемика и словообразование',f:'словообразующ[а-яё]* (?:морфем[а-яё]*|суффикс[а-яё]*)',at:'sc4',ch:'sostav',see:['pref','suff','sc_formoobr']},
 sc_beglyj:{t:'Беглый гласный',d:'Гласный о или е, который исчезает при изменении слова или при образовании родственного слова.',ex:'сон — сна, день — дня, лёд — льда',cat:'Морфемика и словообразование',f:'бегл[а-яё]* гласн[а-яё]*',at:'sc3',ch:'sostav',see:['cheredov','koren']},
 sc_soed:{t:'Соединительная гласная',d:'Гласная о или е между двумя корнями сложного слова. Она не принадлежит ни одному из корней.',ex:'пар-о-воз, земл-е-коп, птиц-е-лов',cat:'Морфемика и словообразование',f:'соединительн[а-яё]* гласн[а-яё]*',at:'sc5',ch:'sostav',see:['slozhn','koren']},
 sc_opr:{t:'Опрощение',d:'Изменение в составе слова: основа, прежде членимая на части, со временем стала нечленимой, потому что связь с родственными словами потеряна.',ex:'вкус (ср. кусать), забор, дворец, красный',cat:'Морфемика и словообразование',f:'опрощени[а-яё]*',at:'sc1',ch:'sostav',see:['morfema','osnova']},
 chislo:{t:'Число',d:'Признак, который показывает, один предмет или несколько. Число бывает единственное и множественное.',ex:'читающий — читающие; книга — книги',cat:'Морфология',f:'(?:единственн|множественн)[а-яё]* числ(?:о|а|у|ом|е)',at:'su3',ch:'sush',see:['rod','padezh','soglas']},
 chlen:{t:'Член предложения',d:'Слово или сочетание слов, которое выполняет в предложении определённую роль. Главные члены — подлежащее и сказуемое, второстепенные — определение, дополнение и обстоятельство.',ex:'Прочитанная (опр.) книга (подл.) лежит (сказ.) на столе (обст.).',cat:'Синтаксис и пунктуация',f:'член[а-яё]* предложени[а-яё]*',at:'su0',ch:'prostoe',see:['podl','skaz','opred','dop']},
 shipyash:{t:'Шипящие',d:'Согласные звуки [ж], [ш], [ч\'], [щ\']: при их произнесении слышится шипение. [ж] и [ш] всегда твёрдые, [ч\'] и [щ\'] всегда мягкие. После шипящих пишутся буквы по особым правилам: жи, ши — с и, ча, ща — с а; о и ё после шипящих — в главе «О и Ё после шипящих».',ex:'жук, шар, час, щука',cat:'Орфография',f:'шипящ(?:ие|их|им|ими)',at:'zv3',ch:'zvuki',see:['soglasn','tverd','myagk']},
 norma:{t:'Языковая норма',d:'Принятое в литературном языке правило произношения, написания или употребления слова. Нормы записаны в словарях и справочниках, например в Правилах 2006 года.',ex:'звони́т (не «зво́нит»); [што] (не [ч\'то]); коридор (не «колидор»)',cat:'Общие понятия',f:'языков[а-яё]* норм[а-яё]*|литературн[а-яё]* норм[а-яё]*',at:'pz1',ch:'normy',see:['lityaz','orfogr','razgovor']},
 // лексика: глава «Слово и его значение» (leks)
 leksika:{t:'Лексика',d:'Все слова языка, его словарный состав. Раздел науки о языке, который изучает слова и их значения, — лексикология.',ex:'исконные и заимствованные, общеупотребительные и диалектные слова',cat:'Лексика',f:'лексик(?:а|и|е|у|ой)|лексикологи(?:я|и|ю|ей)',at:'lk1',ch:'leks',see:['znach','tolk_sl']},
 tolkov:{t:'Толкование',d:'Объяснение лексического значения слова: описанием, близким по смыслу словом, однокоренным или противоположным по смыслу словом. Хорошее толкование можно подставить в предложение вместо слова.',ex:'сугроб — куча снега, наметённая ветром; отважный — смелый; смелость — свойство смелого',cat:'Лексика',f:'толковани(?:е|я|ю|ем|и|й|ям|ями|ях)',at:'lk1',ch:'leks',see:['znach','tolk_sl']},
 tolk_sl:{t:'Толковый словарь',d:'Словарь, который объясняет значения слов. Значения многозначного слова даны в одной статье под номерами; пометы показывают переносные, устаревшие, местные слова.',ex:'словари В. И. Даля, Д. Н. Ушакова, С. И. Ожегова',cat:'Лексика',f:'толков(?:ый|ого|ому|ым|ом|ые|ых|ыми) словар[а-яё]*',at:'lk1',ch:'leks',see:['slov_st','pometa','znach','mnogozn']},
 slov_st:{t:'Словарная статья',d:'Часть словаря, посвящённая одному слову: заголовочное слово с ударением, пометы, толкования значений под номерами, примеры, устойчивые сочетания.',ex:'ЗОЛОТО́Й. 1. Сделанный из золота. 2. Цвета золота. 3. перен. Очень хороший.',cat:'Лексика',f:'словарн(?:ая|ой|ую|ые|ых|ым|ыми|ое) стать[а-яё]*',at:'lk1',ch:'leks',see:['tolk_sl','zagol_sl','pometa']},
 zagol_sl:{t:'Заголовочное слово',d:'Слово, которому посвящена словарная статья. Стоит в начале статьи в начальной форме, со знаком ударения.',ex:'ЗОЛОТО́Й, КАФТА́Н, ИДТИ́',cat:'Лексика',f:'заголовочн(?:ое|ого|ому|ым|ом|ые|ых) слов(?:о|а|у|ом|е)?',at:'lk6',ch:'leks',see:['slov_st','nach_forma']},
 pometa:{t:'Помета',d:'Сокращённая отметка в словарной статье. Одни пометы говорят о значении (перен. — переносное), другие — о том, где и когда слово уместно (устар., разг., книжн., обл., спец.).',ex:'золотые руки — перен.; очи — устар.; электричка — разг.; векша — обл.',cat:'Лексика',f:'помет(?:а|ы|у|ой|е|ам|ами|ах)',at:'lk1',ch:'leks',see:['slov_st','tolk_sl']},
 nach_forma:{t:'Начальная форма',d:'Форма, в которой слово стоит в словаре. У названия предмета — один предмет, вопрос «кто? что?»; у названия признака — вопрос «какой?»; у названия действия — «что делать? что сделать?».',ex:'по дорогам → дорога; тёплую → тёплый; летит → лететь',cat:'Лексика',f:'начальн(?:ая|ой|ую|ые) форм(?:а|ы|у|ой|е)',at:'lk6',ch:'leks',see:['zagol_sl','forma']},
 encikl:{t:'Энциклопедия',d:'Справочное издание (энциклопедический словарь), которое рассказывает не о словах, а о самих предметах, людях, странах, событиях.',ex:'о Волге: длина, притоки, города на берегах',cat:'Лексика',f:'энциклопеди(?:я|и|ю|ей|й|ям|ями|ях)|энциклопедическ(?:ий|ого|ому|им|ом|ие|их) словар[а-яё]*',at:'lk6',ch:'leks',see:['lingv_sl','tolk_sl']},
 lingv_sl:{t:'Лингвистический словарь',d:'Словарь, который рассказывает о словах: что слово значит, как пишется и произносится, откуда пришло. Толковый, орфографический, орфоэпический, этимологический словари — лингвистические.',ex:'о слове «берёза»: значение, ударение, примеры употребления',cat:'Лексика',f:'лингвистическ(?:ий|ого|ому|им|ом|ие|их|ими) словар[а-яё]*',at:'lk6',ch:'leks',see:['encikl','tolk_sl','orfogr_sl']},
 orfogr_sl:{t:'Орфографический словарь',d:'Словарь, который показывает, как пишутся слова. В статье — слово с ударением и трудные формы, без толкований.',ex:'ве́треный; ко́жаный; ле́стница',cat:'Лексика',f:'орфографическ(?:ий|ого|ому|им|ом|ие|их|ими) словар[а-яё]*',at:'lk6',ch:'leks',see:['orfoep_sl','tolk_sl']},
 sl_sinon:{t:'Словарь синонимов',d:'Словарь, в котором слова собраны рядами близких по смыслу. Помогает выбрать точное слово и не повторяться.',ex:'смелый, храбрый, отважный, бесстрашный',cat:'Лексика',f:'словар[а-яё]* синонимов',at:'lk6',ch:'leks',see:['sinonim','tolk_sl']},
 frazeol_sl:{t:'Фразеологический словарь',d:'Словарь устойчивых выражений: объясняет смысл каждого и показывает его в примерах.',ex:'бить баклуши — бездельничать; рукой подать — близко',cat:'Лексика',f:'фразеологическ(?:ий|ого|ому|им|ом|ие|их|ими) словар[а-яё]*',at:'lk6',ch:'leks',see:['frazeol','ustoich']},
 sl_inostr:{t:'Словарь иностранных слов',d:'Словарь заимствованных слов: сообщает, из какого языка пришло слово и что оно значит.',ex:'абажур — из французского; футбол — из английского',cat:'Лексика',f:'словар[а-яё]* иностранных слов',at:'lk6',ch:'leks',see:['zaimstv','etim_sl']},
 etim_sl:{t:'Этимологический словарь',d:'Словарь, который рассказывает историю слов: как слово возникло и с какими словами оно в родстве. В нём есть и исконные, и заимствованные слова.',ex:'медведь — «тот, кто ест мёд»; букашка — от старинного «бук» (жужжание)',cat:'Лексика',f:'этимологическ(?:ий|ого|ому|им|ом|ие|их|ими) словар[а-яё]*',at:'lk6',ch:'leks',see:['sl_inostr','iskon']},
 kontekst:{t:'Контекст',d:'Окружение слова — соседние слова и предложения. По контексту понятно, в каком значении употреблено многозначное слово.',ex:'часы идут (работают) — дождь идёт (падает)',cat:'Лексика',f:'контекст(?:а|у|ом|е)?',at:'lk1',ch:'leks',see:['mnogozn','znach']},
 odnozn:{t:'Однозначное слово',d:'Слово, у которого одно лексическое значение. Обычно это термины и названия узких, конкретных предметов.',ex:'троллейбус, подоконник, бинокль, гипотенуза',cat:'Лексика',f:'однозначн(?:ое|ые|ых|ого|ому|ым|ыми) слов(?:о|а|ам|ами|ах)?',at:'lk2',ch:'leks',see:['mnogozn','termin']},
 mnogozn:{t:'Многозначное слово',d:'Слово, у которого два значения и больше, связанные между собой общим признаком. Нужное значение показывает контекст.',ex:'нос человека — нос лодки; часы идут — человек идёт',cat:'Лексика',f:'многозначн(?:ое|ые|ых|ого|ому|ым|ыми) слов(?:о|а|ам|ами|ах)?|многозначност(?:ь|и|ью)',at:'lk2',ch:'leks',see:['odnozn','pryam','perenosn','omonim']},
 pryam:{t:'Прямое значение',d:'Основное значение слова: оно прямо называет предмет, признак или действие.',ex:'золотое кольцо, железный гвоздь, нос человека',cat:'Лексика',f:'прям(?:ое|ого|ому|ым|ом) значени[а-яё]*',at:'lk3',ch:'leks',see:['perenosn','mnogozn']},
 perenosn:{t:'Переносное значение',d:'Значение, которое появилось, когда название перенесли с одного предмета, признака, действия на другой — по сходству (метафора) или по смежности (метонимия). В словаре — помета «перен.».',ex:'золотые руки, нос лодки, ветер воет, съел тарелку супа',cat:'Лексика',f:'переносн(?:ое|ого|ому|ым|ом|ые|ых|ыми) значени[а-яё]*',at:'lk3',ch:'leks',see:['pryam','metafora','metonim']},
 metafora:{t:'Метафора',d:'Перенос названия по сходству: форме, цвету, расположению, назначению, свойствам. Метафору можно развернуть в сравнение с «как».',ex:'шляпка гриба, золотая осень, хвост поезда, железная воля',cat:'Лексика',f:'метафор(?:а|ы|е|у|ой|ами|ах|ам)?|метафорическ[а-яё]*',at:'lk3',ch:'vyraz',see:['perenosn','olicetv','metonim']},
 olicetv:{t:'Олицетворение',d:'Вид метафоры: неживое наделяется свойствами живого — говорит, спит, плачет, сердится.',ex:'ветер злится, лес спит, «Лениво дышит полдень мглистый» (Ф. И. Тютчев)',cat:'Лексика',f:'олицетворени(?:е|я|ю|ем|и|й|ями|ях)',at:'lk3',ch:'vyraz',see:['metafora']},
 metonim:{t:'Метонимия',d:'Перенос названия по смежности — на то, что связано с предметом: посуда — содержимое, место — люди, материал — изделие, автор — произведения.',ex:'съел тарелку супа, весь класс пошёл в музей, читать Пушкина, получил золото',cat:'Лексика',f:'метоними(?:я|и|ю|ей|й|ями)',at:'lk3',ch:'vyraz',see:['perenosn','metafora','sinekdoha']},
 sinekdoha:{t:'Синекдоха',d:'Вид метонимии: целое называют по части или по заметной примете.',ex:'в семье пять ртов; ни одной живой души; светлая голова',cat:'Лексика',f:'синекдох(?:а|и|у|ой|е)',at:'lk3',ch:'vyraz',see:['metonim']},
 iskon:{t:'Исконно русские слова',d:'Слова, которые возникли в русском языке или достались ему от языков-предков (общеславянские, восточнославянские).',ex:'берёза, дом, голова, хороший, зажигалка',cat:'Лексика',f:'исконн(?:о|ые|ых|ое|ого|ым|ыми|ая|ой)(?: русск(?:ие|их|ое|ого|им|ими|ая|ой))?',at:'pz1',ch:'leks',see:['zaimstv','staroslav']},
 zaimstv:{t:'Заимствованное слово',d:'Слово, пришедшее из другого языка. Приметы: начальные а и э, буква ф, две гласные подряд, неизменяемость; у многих давних заимствований примет нет.',ex:'тетрадь (греч.), сарафан (тюрк.), галстук (нем.), пальто (франц.), футбол (англ.)',cat:'Лексика',f:'заимствованн(?:ое|ые|ых|ого|ому|ым|ыми|ая|ой) слов[а-яё]*|заимствовани(?:е|я|ю|ем|и|й|ями|ях)',at:'pz1',ch:'leks',see:['iskon','staroslav','ekzotizm']},
 staroslav:{t:'Старославянизм',d:'Слово, пришедшее из старославянского языка церковных книг. Примета — сочетания ра, ла, ре, ле на месте русских оро, оло, ере; жд на месте ж; щ на месте ч.',ex:'град — город, злато — золото, брег — берег, чуждый — чужой, освещение — свеча',cat:'Лексика',f:'старославянизм[а-яё]*',at:'lk4',ch:'leks',see:['iskon','zaimstv','arhaizm']},
 istorizm:{t:'Историзм',d:'Устаревшее слово, которое называет исчезнувший предмет или явление; современной замены у него нет.',ex:'кафтан, боярин, кольчуга, ямщик, лучина, верста',cat:'Лексика',f:'историзм(?:ы|а|у|ом|е|ов|ам|ами|ах)?',at:'lk4',ch:'leks',see:['arhaizm','neolog','ustar']},
 arhaizm:{t:'Архаизм',d:'Устаревшее название предмета или явления, которое есть и сейчас, но называется другим словом.',ex:'очи — глаза, чело — лоб, перст — палец, ветрило — парус, брег — берег',cat:'Лексика',f:'архаизм(?:ы|а|у|ом|е|ов|ам|ами|ах)?',at:'lk4',ch:'leks',see:['istorizm','staroslav','ustar']},
 neolog:{t:'Неологизм',d:'Новое слово (или новое значение слова), которое ещё воспринимается как непривычное. Со временем становится обычным.',ex:'в 1960-х — слово космонавт, в 1970 году — луноход; новое значение — спутник (аппарат), мышь (у компьютера)',cat:'Лексика',f:'неологизм(?:ы|а|у|ом|е|ов|ам|ами|ах)?',at:'lk4',ch:'leks',see:['istorizm','zaimstv']},
 ekzotizm:{t:'Экзотизм',d:'Заимствованное слово, которое называет предмет чужой жизни и употребляется только о ней.',ex:'сакля, юрта, кимоно, рикша, вигвам',cat:'Лексика',f:'экзотизм[а-яё]*',at:'lk4',ch:'leks',see:['zaimstv']},
 obsheup:{t:'Общеупотребительные слова',d:'Слова, которые знают и употребляют все, кто говорит по-русски. Остальные — слова ограниченного употребления: диалектизмы, термины, профессионализмы, жаргонизмы.',ex:'вода, хлеб, дом, идти, добрый',cat:'Лексика',f:'общеупотребительн(?:ые|ых|ое|ого|ым|ыми|ая|ой)(?: слов[а-яё]*)?',at:'lk5',ch:'leks',see:['dialekt','termin','profess','zhargon']},
 dialekt:{t:'Диалектизм',d:'Слово местного говора (диалекта), которое употребляют жители одной местности. В словаре — помета «обл.».',ex:'кочет — петух, векша — белка, гутарить — говорить, умет — постоялый двор',cat:'Лексика',f:'диалектизм(?:ы|а|у|ом|е|ов|ам|ами|ах)?|диалект(?:а|у|ом|е|ы|ов|ам|ах)?',at:'lk5',ch:'leks',see:['obsheup','profess','zhargon']},
 termin:{t:'Термин',d:'Официальное точное название понятия науки или техники. Термин однозначен и не несёт оттенка чувства.',ex:'орфограмма, гипотенуза, биссектриса, молекула',cat:'Лексика',f:'термин(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'lk2',ch:'leks',see:['profess','odnozn','obsheup']},
 profess:{t:'Профессионализм',d:'Неофициальное, часто образное слово людей одной профессии, которым в живой речи заменяют термин.',ex:'баранка — руль (у шофёров), шкурка — наждачная бумага (у столяров), свеча — резкий подъём температуры на графике (у врачей)',cat:'Лексика',f:'профессионализм(?:ы|а|у|ом|е|ов|ам|ами|ах)?',at:'lk5',ch:'leks',see:['termin','zhargon']},
 zhargon:{t:'Жаргонизм',d:'Слово, которое употребляют в узкой группе людей (школьники, студенты, любители компьютерных игр). В литературной речи неуместно.',ex:'шпора — шпаргалка, физра — физкультура, клава — клавиатура',cat:'Лексика',f:'жаргонизм(?:ы|а|у|ом|е|ов|ам|ами|ах)?|жаргон(?:а|у|ом|е)?',at:'lk5',ch:'leks',see:['dialekt','profess','obsheup']},
 sochet:{t:'Лексическая сочетаемость',d:'Способность слов соединяться друг с другом по смыслу. Её нарушение — лексическая ошибка, часто от смешения двух выражений.',ex:'доставить радость, но причинить горе; нанести вред, но оказать помощь',cat:'Лексика',f:'лексическ(?:ая|ой|ую) сочетаемост(?:ь|и|ью)|сочетаемост(?:ь|и|ью)',at:'lk5',ch:'leknorm',see:['pleonazm','tavtol']},
 lex_norma:{t:'Лексическая норма',d:'Правила выбора и употребления слов в литературном языке: слово берут в его точном значении, в принятом сочетании, без лишних слов и к месту.',ex:'надеть пальто (не «одеть»); одержать победу (не «поражение»)',cat:'Лексика',f:'лексическ(?:ая|ой|ую|ие|их) норм[а-яё]*',at:'lx1',ch:'leknorm',see:['lex_osh','norma','sochet']},
 lex_osh:{t:'Лексическая ошибка',d:'Нарушение лексической нормы: виновато само слово — оно неточно, не сочетается с соседним, лишнее или неуместное. Исправляют заменой слова (либо слово убирают или добавляют).',ex:'«одолжил у соседа» вместо «занял»; «памятный сувенир»',cat:'Лексика',f:'лексическ(?:ая|ой|ую|ие|их) ошибк[а-яё]*',at:'lk5',ch:'leknorm',see:['lex_norma','gram_osh','pleonazm']},
 tochn:{t:'Точность речи',d:'Качество речи: слово строго соответствует тому, что оно обозначает. Проверка — подставить на место слова его толкование из словаря.',ex:'Колумб открыл (не «изобрёл») Америку',cat:'Лексика',f:'точност(?:ь|и|ью) речи',at:'lx1',ch:'leknorm',see:['lex_norma','tolk_sl']},
 kontam:{t:'Контаминация',d:'Смешение двух близких оборотов: от каждого берётся половина, и получается ошибочное сочетание.',ex:'«играть значение» = играть роль + иметь значение',cat:'Лексика',f:'контаминаци[а-яё]*',at:'lx2',ch:'leknorm',see:['sochet','lex_osh']},
 rech_izb:{t:'Речевая избыточность',d:'Многословие: в речи есть слова, которые ничего не добавляют к сказанному. Виды — плеоназм и тавтология.',ex:'в мае месяце; рассказчик рассказал',cat:'Лексика',f:'речев(?:ая|ой|ую) избыточност[а-яё]*',at:'lx4',ch:'leknorm',see:['pleonazm','tavtol','rech_ned']},
 rech_ned:{t:'Речевая недостаточность',d:'Пропуск слова, без которого мысль неясна или смешна.',ex:'«На стене висели писатели» — нужно: портреты писателей',cat:'Лексика',f:'речев(?:ая|ой|ую) недостаточност[а-яё]*',at:'lx4',ch:'leknorm',see:['rech_izb']},
 parazit:{t:'Слова-паразиты',d:'Слова, которые говорящий повторяет часто и без смысла; их можно убрать, и содержание не изменится.',ex:'ну, вот, значит, как бы, это самое, короче',cat:'Лексика',f:'слов(?:о|а|ами|ам|ах)?-паразит[а-яё]*',at:'lx5',ch:'leknorm',see:['sv_kanc','sv_shtamp']},
 alogizm:{t:'Алогизм',d:'Нарушение логики в высказывании: сравнивают несравнимое, подменяют понятие, берут слишком широкое или слишком узкое слово.',ex:'«Клюв снегиря короче, чем дятел» — нужно: чем клюв дятла',cat:'Лексика',f:'алогизм[а-яё]*',at:'lx6',ch:'leknorm',see:['lex_osh','rech_ned']},
 // фразеология (глава «Фразеологизмы»)
 frazeol:{t:'Фразеологизм',d:'Устойчивое сочетание слов с единым значением, которое не складывается из значений слов. Его употребляют в готовом виде; слова в нём не заменяют. Часто равен по смыслу одному слову.',ex:'бить баклуши — бездельничать; рукой подать — близко; как снег на голову — неожиданно',cat:'Лексика',f:'фразеологизм[а-яё]*|фразеологическ(?:ий|ого|им|ом|ие|их) оборот[а-яё]*',at:'lk1',ch:'fraz',see:['svob_soch','frazeologia','krylat','poslov']},
 frazeologia:{t:'Фразеология',d:'Все фразеологизмы языка. Раздел науки о языке, который изучает устойчивые обороты: их значение, происхождение и употребление.',ex:'бить баклуши, ахиллесова пята, тришкин кафтан',cat:'Лексика',f:'фразеологи(?:я|и|ю|ей)',at:'fr1',ch:'fraz',see:['frazeol','leksika']},
 svob_soch:{t:'Свободное сочетание',d:'Сочетание слов, которое говорящий строит сам: каждое слово сохраняет своё значение и может быть заменено другим. Противопоставлено фразеологизму.',ex:'железная лопата, деревянная лопата; сел в лужу (упал) — свободное, сел в лужу (опозорился) — фразеологизм',cat:'Лексика',f:'свободн(?:ое|ого|ым|ом|ые|ых|ыми) сочетани[а-яё]*',at:'fr1',ch:'fraz',see:['frazeol','kontekst']},
 krylat:{t:'Крылатые слова',d:'Меткие выражения из книг и речей, которые все знают и повторяют: строки писателей, названия произведений, имена героев.',ex:'«А ларчик просто открывался» (И. А. Крылов); «Счастливые часов не наблюдают» (А. С. Грибоедов); у разбитого корыта (А. С. Пушкин)',cat:'Лексика',f:'крылат(?:ые|ых|ым|ыми) слов(?:а|ам|ами|ах)?|крылат(?:ое|ого|ым|ые|ых) выражени[а-яё]*',at:'fr3',ch:'fraz',see:['frazeol','poslov']},
 poslov:{t:'Пословица',d:'Краткое народное изречение — законченное предложение с поучением, выводом.',ex:'Семь раз отмерь — один раз отрежь. Без труда не вытащишь и рыбку из пруда.',cat:'Лексика',f:'пословиц[а-яё]*',at:'lk1',ch:'fraz',see:['pogov','frazeol']},
 pogov:{t:'Поговорка',d:'Меткое народное выражение без поучения: оно образно оценивает человека или событие, но вывода не содержит. Граница между поговоркой и фразеологизмом нечёткая.',ex:'Вот тебе, бабушка, и Юрьев день. Лёгок на помине. Чудеса в решете.',cat:'Лексика',f:'поговорк[а-яё]*|поговорок',at:'fr4',ch:'fraz',see:['poslov','frazeol']},
 // глава «НЕ и НИ»
 otr_mest:{t:'Отрицательные местоимения',d:'Местоимения, которые отрицают наличие предмета или признака: образованы с помощью не или ни. Под ударением пишется не, без ударения — ни; без предлога — слитно, с предлогом — в три слова.',ex:'некого, нечего, никто, ничей; не у кого, ни о чём',cat:'Морфология',f:'отрицательн(?:ое|ого|ым|ом|ые|ых|ыми) местоимени[а-яё]*',at:'ne5',ch:'mest',see:['otr_nar','mest','chast_ni']},
 otr_nar:{t:'Отрицательные наречия',d:'Наречия, которые отрицают место, время, направление, причину. Пишутся слитно; под ударением — не, без ударения — ни.',ex:'негде — нигде, некуда — никуда, некогда — никогда, неоткуда — ниоткуда, незачем',cat:'Морфология',f:'отрицательн(?:ое|ого|ым|ом|ые|ых|ыми) наречи[а-яё]*',at:'ne5',ch:'narech',see:['otr_mest','narech','chast_ni']},
 chast_ni:{t:'Частица ни',d:'Усилительная частица: усиливает отрицание, которое уже есть в предложении; повторяясь, соединяет однородные члены; после слов кто, что, где, как, сколько обобщает («всё равно кто, где»). Пишется раздельно, кроме отрицательных местоимений и наречий.',ex:'нет ни души; ни дождь, ни ветер не помешали; куда ни взглянешь — всюду цветы',cat:'Морфология',f:'частиц[а-яё]* ни(?=[^а-яё]|$)',at:'ne6',ch:'ne',see:['chastica','otr_mest','otr_nar']},
 chisl:{t:'Числительное',d:'Самостоятельная часть речи, которая обозначает количество предметов (количественные) или порядок при счёте (порядковые).',ex:'три, сто, пятеро; первый, десятый',cat:'Морфология',f:'числительн[а-яё]*',at:'su0',ch:'chisl',see:['chast_rechi','mest']},
 odnor:{t:'Однородные члены предложения',d:'Члены предложения, которые относятся к одному и тому же слову и отвечают на один вопрос; соединяются союзами или интонацией перечисления.',ex:'ни дождь, ни ветер; яблоки, груши и сливы',cat:'Синтаксис и пунктуация',f:'однородн(?:ые|ых|ыми|ым) член[а-яё]*',at:'pr7',ch:'odnor',see:['soyuz','chlen']},
 otn_pril:{t:'Относительное прилагательное',d:'Прилагательное, которое обозначает признак через отношение к предмету: материал, место, время, принадлежность. Не имеет степеней сравнения и краткой формы. С не пишется раздельно: противопоставление подразумевается.',ex:'деревянный, шерстяной, летний, школьный; стол не деревянный',cat:'Морфология',f:'относительн(?:ое|ого|ому|ым|ом|ые|ых|ыми) прилагательн[а-яё]*',at:'pl2',ch:'pril',see:['pril','razryad']},
 gram_norma:{t:'Грамматическая норма',d:'Принятые в литературном языке правила образования форм слов (морфологические нормы) и их связи в словосочетании и предложении (синтаксические нормы).',ex:'много помидоров (не «помидор»); оплатить проезд (не «за проезд»)',cat:'Общие понятия',f:'грамматическ(?:ая|ой|ую|ие|их|им|ими) норм[а-яё]*',at:'nm1',ch:'normy',see:['norma','gram_osh','upravl','soglas']},
 gram_osh:{t:'Грамматическая ошибка',d:'Нарушение грамматической нормы: неверная форма слова или неверная связь слов в словосочетании и предложении.',ex:'«ляжь» вместо «ляг»; «кто из ребят пришли» вместо «пришёл»',cat:'Общие понятия',f:'грамматическ(?:ая|ой|ую|ие|их|им|ими) ошибк[а-яё]*',at:'nm1',ch:'normy',see:['gram_norma','norma']},
 prityazh:{t:'Притяжательное местоимение',d:'Местоимение, которое отвечает на вопрос «чей?» и указывает на принадлежность. Его, её, их в значении «чей?» не изменяются и после предлогов пишутся без н.',ex:'мой, твой, свой, наш; у его брата, к её дому',cat:'Морфология',f:'притяжательн(?:ое|ого|ому|ым|ом|ые|ых|ыми) местоимен[а-яё]*',at:'rc5',ch:'mest',see:['mest','lichmest']},
 sostav_chisl:{t:'Составное числительное',d:'Числительное из нескольких слов. В составном количественном числительном склоняется каждое слово, в порядковом — только последнее.',ex:'с тремястами двадцатью пятью рублями; в две тысячи двадцать пятом году',cat:'Морфология',f:'составн(?:ое|ого|ому|ым|ом|ые|ых|ыми) (?:количественн[а-яё]* |порядков[а-яё]* )?числительн[а-яё]*',at:'nm3',ch:'chisl',see:['chisl','poryad']},
 poryad:{t:'Порядковое числительное',d:'Числительное, которое обозначает порядок предметов при счёте и отвечает на вопрос «который?»; изменяется как прилагательное.',ex:'первый, десятый, двадцать пятый',cat:'Морфология',f:'порядков(?:ое|ого|ому|ым|ом|ые|ых|ыми) числительн[а-яё]*',at:'nm3',ch:'chisl',see:['chisl','sostav_chisl']},
 sobir_chisl:{t:'Собирательные числительные',d:'Числительные двое, трое, четверо и т. д., которые обозначают количество как одно целое. Употребляются с названиями лиц мужского пола, со словами дети, люди, ребята, с существительными без единственного числа; с названиями лиц женского пола и взрослых животных не употребляются.',ex:'двое друзей, трое детей, двое суток; но две подруги',cat:'Морфология',f:'собирательн(?:ое|ого|ому|ым|ом|ые|ых|ыми) числительн[а-яё]*',at:'nm3',ch:'chisl',see:['chisl']},
 kosv_rech:{t:'Косвенная речь',d:'Чужая речь, переданная от лица рассказчика придаточной частью сложного предложения; местоимения и формы глагола меняются с точки зрения рассказчика.',ex:'Брат сказал, что устал.',cat:'Синтаксис и пунктуация',f:'косвенн(?:ая|ой|ую) реч[а-яё]*',at:'rc1',ch:'rech',see:['rc_pryam','rc_chuzh','predl']},
 // сложное предложение (глава slozhnoe)
 gramosn:{t:'Грамматическая основа',d:'Подлежащее и сказуемое вместе (или один главный член в односоставном предложении). По числу основ узнают простое и сложное предложение.',ex:'Ветер стих, и тучи разошлись: ветер стих; тучи разошлись',cat:'Синтаксис и пунктуация',f:'грамматическ(?:ая|ой|ую|ие|их|ими) основ[а-яё]*',at:'sz1',ch:'prostoe',see:['podl',  'skaz',  'slozhnpr']},
 slozhnpr:{t:'Сложное предложение',d:'Предложение с двумя и более грамматическими основами; части связаны союзами, союзными словами или без союзов, интонацией.',ex:'Прозвенел звонок, и урок начался.',cat:'Синтаксис и пунктуация',f:'сложн(?:ое|ого|ому|ым|ом|ые|ых|ыми) предложени[а-яё]*',at:'pr7',ch:'slozhnoe',see:['gramosn',  'ssp',  'spp',  'bsp']},
 ssp:{t:'Сложносочинённое предложение',d:'Сложное предложение, части которого равноправны и соединены сочинительными союзами.',ex:'Дул ветер, и шумели сосны.',cat:'Синтаксис и пунктуация',f:'сложносочинённ[а-яё]*(?: предложени[а-яё]*)?',at:'sz1',ch:'ssp',see:['sochsoyuz',  'slozhnpr']},
 spp:{t:'Сложноподчинённое предложение',d:'Сложное предложение из главной и придаточной части; придаточная присоединяется подчинительным союзом или союзным словом и отвечает на вопрос от главной.',ex:'Мы вернулись, когда стемнело.',cat:'Синтаксис и пунктуация',f:'сложноподчинённ[а-яё]*(?: предложени[а-яё]*)?',at:'sz1',ch:'spp',see:['glavchast',  'pridat',  'soyuzslovo']},
 bsp:{t:'Бессоюзное сложное предложение',d:'Сложное предложение, части которого связаны без союзов — смыслом и интонацией; знак между частями выбирают по смыслу.',ex:'Пора вставать: уже семь часов.',cat:'Синтаксис и пунктуация',f:'бессоюзн(?:ое|ого|ому|ым|ом|ые|ых|ыми) сложн[а-яё]* предложени[а-яё]*',at:'sz1',ch:'bsp',see:['slozhnpr']},
 sochsoyuz:{t:'Сочинительные союзы',d:'Союзы, которые соединяют равноправные части: соединительные (и, да, ни… ни), противительные (а, но, зато, однако), разделительные (или, либо, то… то).',ex:'и, а, но, или, то… то',cat:'Синтаксис и пунктуация',f:'сочинительн(?:ые|ых|ыми|ым|ый|ого|ому|ым) союз[а-яё]*',at:'sz1',ch:'sluzh',see:['soyuz',  'ssp']},
 glavchast:{t:'Главная часть',d:'Часть сложноподчинённого предложения, от которой задают вопрос к придаточной.',ex:'[Мы вышли в сад], когда кончился дождь.',cat:'Синтаксис и пунктуация',f:'главн(?:ая|ой|ую) част[а-яё]*',at:'dr3',ch:'spp',see:['pridat',  'spp']},
 pridat:{t:'Придаточная часть',d:'Зависимая часть сложноподчинённого предложения: отвечает на вопрос от главной и присоединяется союзом или союзным словом.',ex:'Мы вышли в сад, (когда?) когда кончился дождь.',cat:'Синтаксис и пунктуация',f:'придаточн(?:ая|ой|ую|ые|ых|ыми) част[а-яё]*',at:'dr3',ch:'spp',see:['glavchast',  'spp']},
 soyuzslovo:{t:'Союзное слово',d:'Местоимение или наречие (который, кто, что, где, когда, как), которое присоединяет придаточную часть и само является её членом.',ex:'Я нашёл книгу, которую искал (которую — дополнение).',cat:'Синтаксис и пунктуация',f:'союзн(?:ое|ого|ому|ым|ые|ых|ыми) слов[а-яё]*',at:'dr3',ch:'spp',see:['soyuz',  'pridat']},
 ukazslovo:{t:'Указательное слово',d:'Местоимение или наречие в главной части (тот, то, такой, там, туда, тогда, так), на которое указывает придаточная.',ex:'Счастлив тот, кто любит своё дело.',cat:'Синтаксис и пунктуация',f:'указательн(?:ое|ого|ые|ых|ым|ыми) слов[а-яё]*',at:'sz3',ch:'spp',see:['pridat',  'glavchast']},
 sostsoyuz:{t:'Составной союз',d:'Союз из нескольких слов (потому что, так как, после того как, для того чтобы); обычно не разбивается запятой.',ex:'Мы ушли, так как стемнело.',cat:'Синтаксис и пунктуация',f:'составн(?:ой|ого|ому|ым|ые|ых|ыми) союз[а-яё]*',at:'sz3',ch:'spp',see:['soyuz',  'spp']},
 posledpodch:{t:'Последовательное подчинение',d:'Придаточные образуют цепочку: вторая зависит от первой, третья — от второй.',ex:'Я знаю, что в лесу, куда мы идём, растут грибы.',cat:'Синтаксис и пунктуация',f:'последовательн(?:ое|ого|ом|ым) подчинени[а-яё]*',at:'sz5',ch:'spp2',see:['odnorpodch',  'parallpodch']},
 odnorpodch:{t:'Однородное подчинение',d:'Придаточные одного вида относятся к одному слову главной части и отвечают на один вопрос.',ex:'Мы видели, как садилось солнце и как поднимался туман.',cat:'Синтаксис и пунктуация',f:'однородн(?:ое|ого|ом|ым) подчинени[а-яё]*',at:'sz5',ch:'spp2',see:['posledpodch',  'parallpodch']},
 parallpodch:{t:'Параллельное подчинение',d:'Придаточные разных видов (или к разным словам) относятся к главной части.',ex:'Когда мы пришли, мама сказала, что звонил дядя.',cat:'Синтаксис и пунктуация',f:'параллельн(?:ое|ого|ом|ым) подчинени[а-яё]*',at:'sz5',ch:'spp2',see:['posledpodch',  'odnorpodch']},
 // стилистика (глава «Стили речи», stili): составные термины раньше общих
 sv_stil:{t:'Стиль речи',d:'Разновидность литературного языка, которая служит одной сфере общения и одной главной задаче; в каждом стиле свой отбор слов, форм и конструкций. Стили: разговорный и книжные — научный, официально-деловой, публицистический, художественный.',ex:'одна новость — в разговоре, в газете, в протоколе',cat:'Общие понятия',f:'стил(?:ь|я|ю|ем|е|и|ей|ям|ями|ях) речи|функциональн(?:ый|ого|ому|ым|ом|ые|ых|ыми) стил[а-яё]*',at:'tp1',ch:'stili',see:['sv_razg','sv_knizh','sv_okr']},
 sv_knizh:{t:'Книжные стили',d:'Стили подготовленной, чаще письменной речи: научный, официально-деловой, публицистический и художественный. Им противопоставлен разговорный стиль.',ex:'учебник, заявление, газетная статья, рассказ',cat:'Общие понятия',f:'книжн(?:ые|ых|ым|ыми) стил[а-яё]*',at:'tp1',ch:'stili',see:['sv_stil','sv_razg']},
 sv_razg:{t:'Разговорный стиль речи',d:'Стиль непринуждённого общения дома и с друзьями, обычно устный разговор. Он литературный, но свободнее книжной речи: короткие фразы, разговорные слова.',ex:'— Ты куда? — В кино. Пойдёшь со мной?',cat:'Общие понятия',f:'разговорн(?:ый|ого|ому|ым|ом) стил[а-яё]*|разговорн(?:ая|ой|ую) реч(?:ь|и|ью)',at:'pz1',ch:'stili',see:['sv_stil','sv_rzleks','sv_prost']},
 sv_nauch:{t:'Научный стиль',d:'Стиль науки и учёбы. Задача — точно сообщить знания и доказать. Приметы: термины, отвлечённые слова, определения, сложные предложения, вводные слова порядка и вывода. Подстили: собственно научный, научно-учебный, научно-популярный.',ex:'Испарение — переход вещества из жидкого состояния в газообразное.',cat:'Общие понятия',f:'научн(?:ый|ого|ому|ым|ом) стил[а-яё]*',at:'tp1',ch:'stili',see:['termin','sv_podstil','sv_otgl']},
 sv_delo:{t:'Официально-деловой стиль',d:'Стиль законов, приказов и деловых бумаг. Задача — точно сообщить и закрепить. Приметы: деловые слова и клише, отымённые предлоги, отглагольные существительные, нет оценки, строгая форма документа.',ex:'Прошу освободить меня от занятий 14 марта в связи с участием в олимпиаде.',cat:'Общие понятия',f:'официально-делов(?:ой|ого|ому|ым|ом) стил[а-яё]*|делов(?:ой|ого|ому|ым|ом) стил[а-яё]*',at:'tp1',ch:'stili',see:['sv_klishe','sv_rekv','sv_kanc']},
 sv_publ:{t:'Публицистический стиль',d:'Стиль газет, журналов, радио, телевидения и выступлений. Задачи — сообщить о важном для общества и воздействовать: убедить, призвать. Приметы: оценочная и общественно-политическая лексика, риторические вопросы, призывы, повторы.',ex:'Разве можно спокойно смотреть, как пересыхает родник? Берегите воду!',cat:'Общие понятия',f:'публицистическ(?:ий|ого|ому|им|ом) стил[а-яё]*',at:'tp1',ch:'stili',see:['sv_rvopr','sv_shtamp','sv_zhanr']},
 sv_hud:{t:'Художественный стиль',d:'Язык художественной литературы. Задача — создать образ и передать чувство. Черты: образность, эмоциональность, конкретность, личность автора, многостильность; тропы и фигуры речи.',ex:'«Зима недаром злится, / Прошла её пора» (Ф. И. Тютчев)',cat:'Общие понятия',f:'художественн(?:ый|ого|ому|ым|ом) стил[а-яё]*',at:'tp1',ch:'stili',see:['sv_trop','sv_figura','sv_mnogostil']},
 sv_okr:{t:'Стилистическая окраска',d:'Привязанность слова (формы, оборота) к определённому стилю: книжная, разговорная, просторечная. У межстилевых слов окраски нет. В словаре окраску показывают пометы: книжн., высок., офиц., разг., прост.',ex:'похитить (книжн.) — украсть — стащить (разг.)',cat:'Лексика',f:'стилистическ(?:ая|ой|ую) окраск[а-яё]*',at:'fr1',ch:'stili',see:['sv_neitr','sv_knleks','sv_rzleks']},
 sv_neitr:{t:'Межстилевые слова',d:'Нейтральные слова, уместные в любом стиле; основа словаря языка.',ex:'дом, вода, дерево, идти, хороший, пять',cat:'Лексика',f:'межстилев(?:ые|ых|ое|ая|ой|ым|ыми|ыми) (?:слов[а-яё]*|лексик[а-яё]*)|межстилев(?:ыми|ыми|ым|ых|ые)',at:'sv1',ch:'stili',see:['sv_okr','obsheup']},
 sv_knleks:{t:'Книжная лексика',d:'Слова письменной, подготовленной речи: научные, деловые, публицистические, общекнижные. Особая часть — высокие слова. В разговоре звучат строго или неуместно.',ex:'весьма, всецело, ибо, проживать, гражданственность',cat:'Лексика',f:'книжн(?:ые|ых|ое|ая|ой|ым|ыми) (?:слов[а-яё]*|лексик[а-яё]*)',at:'ps1',ch:'stili',see:['sv_vys','sv_rzleks','sv_okr']},
 sv_rzleks:{t:'Разговорная лексика',d:'Слова непринуждённой устной речи, часто с оценкой. Входят в литературный язык: в беседе они уместны, в документе и научном тексте — нет.',ex:'мигом, уйма, зря, чепуха, здоровяк, болтать',cat:'Лексика',f:'разговорн(?:ые|ых|ое|ая|ой|ым|ыми) (?:слов[а-яё]*|лексик[а-яё]*)',at:'zn1',ch:'stili',see:['sv_prost','sv_knleks','sv_okr']},
 sv_vys:{t:'Высокая лексика',d:'Торжественные и поэтические книжные слова; многие из них устаревшие. Придают речи приподнятость.',ex:'отчизна, грядущий, лучезарный, воздвигнуть, чело',cat:'Лексика',f:'высок(?:ие|их|ое|ая|ой|ую|им|ими) (?:слов[а-яё]*|лексик[а-яё]*)',at:'sv1',ch:'stili',see:['sv_knleks','ustar']},
 sv_prost:{t:'Просторечие',d:'Слова и формы, которые лежат за пределами литературной нормы: грубоватые или «простонародные». В словаре — помета «прост.». В книге встречаются в речи героев.',ex:'глазеть, давеча, небось, отродясь, загодя',cat:'Лексика',f:'просторечи[а-яё]*|просторечн[а-яё]*',at:'pz1',ch:'stili',see:['sv_rzleks','zhargon','dialekt']},
 sv_emo:{t:'Эмоционально-экспрессивная окраска',d:'Оценка, которую несёт слово: одобрение, ласка, торжественность или неодобрение, насмешка. Её создают значение слова, переносное употребление, суффиксы оценки.',ex:'белоснежный, солнышко, растяпа, зазнайка',cat:'Лексика',f:'эмоционально-экспрессивн(?:ая|ой|ую) окраск[а-яё]*',at:'sv1',ch:'stili',see:['sv_okr']},
 sv_zhanr:{t:'Жанр',d:'Устойчивый вид высказывания внутри стиля: записка, словарная статья, заявление, расписка, репортаж, интервью, рассказ, басня.',ex:'заявление — жанр делового стиля; репортаж — публицистического',cat:'Общие понятия',f:'жанр(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'tp1',ch:'stili',see:['sv_stil']},
 sv_podstil:{t:'Подстиль',d:'Разновидность стиля. У научного — собственно научный, научно-учебный и научно-популярный; у делового — законодательный, административно-канцелярский, дипломатический.',ex:'учебник — научно-учебный подстиль; познавательная книга — научно-популярный',cat:'Общие понятия',f:'подстил(?:ь|я|ю|ем|е|и|ей|ям|ями|ях)',at:'sv3',ch:'stili',see:['sv_nauch','sv_delo']},
 sv_otgl:{t:'Отглагольное существительное',d:'Существительное, образованное от глагола и называющее действие как предмет. Частая примета научного и делового стиля; в живой речи их избыток — канцелярит.',ex:'нагревание, испарение, выдача, неявка',cat:'Морфология',f:'отглагольн(?:ое|ого|ому|ым|ом|ые|ых|ыми) существительн[а-яё]*',at:'sv3',ch:'stili',see:['sv_kanc']},
 sv_otympr:{t:'Отымённый предлог',d:'Производный предлог, образованный от существительного: в связи с, в течение, по окончании, в целях, на основании. Примета делового и научного стиля.',ex:'в течение недели, по окончании урока',cat:'Морфология',f:'отым[её]нн(?:ый|ого|ому|ым|ом|ые|ых|ыми) предлог[а-яё]*',at:'sv4',ch:'sluzh',see:['predlog','sv_delo']},
 sv_klishe:{t:'Клише',d:'Готовая речевая формула, принятая в определённом жанре; в документе экономит время и исключает двусмысленность.',ex:'прошу разрешить, довожу до вашего сведения, в установленном порядке',cat:'Общие понятия',f:'клише',at:'sv3',ch:'stili',see:['sv_shtamp','sv_kanc']},
 sv_shtamp:{t:'Речевой штамп',d:'Избитое выражение, которое повторяют не думая; оно ничего не сообщает и делает речь бесцветной.',ex:'мероприятие прошло на высоком уровне, внести свою лепту',cat:'Общие понятия',f:'штамп(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'sv4',ch:'stili',see:['sv_klishe','sv_kanc']},
 sv_kanc:{t:'Канцеляризм',d:'Слово или оборот делового стиля, перенесённый туда, где он неуместен: в бытовую речь, сочинение, рассказ. К. И. Чуковский назвал это пристрастие «канцеляритом».',ex:'в данный момент, произвести уборку, имеет место (вместо: сейчас, убрать, бывает)',cat:'Общие понятия',f:'канцеляризм[а-яё]*|канцелярит[а-яё]*',at:'sv4',ch:'stili',see:['sv_klishe','sv_shtamp','sv_otgl']},
 sv_rekv:{t:'Реквизиты документа',d:'Обязательные части документа в установленном порядке: кому, от кого, название, текст, дата, подпись и др. Без них бумага теряет силу.',ex:'заявление: кому — от кого — «Заявление» — просьба — подпись и дата',cat:'Общие понятия',f:'реквизит[а-яё]*',at:'sv4',ch:'stili',see:['sv_delo']},
 sv_trop:{t:'Тропы',d:'Слова и обороты в переносном значении, которые создают художественный образ: эпитет, сравнение, метафора, олицетворение, метонимия, гипербола, литота.',ex:'роща золотая; луна, как бледное пятно; зима злится',cat:'Лексика',f:'троп(?:ы|ов|ам|ами|ах)',at:'sv6',ch:'vyraz',see:['sv_epitet','sv_sravn','metafora','olicetv','sv_giperb','sv_litota']},
 sv_epitet:{t:'Эпитет',d:'Образное определение, которое выделяет признак и выражает отношение говорящего. Не всякое прилагательное — эпитет: «деревянный стол» — просто признак.',ex:'роща золотая, весёлый ручей, хрустальный день',cat:'Лексика',f:'эпитет[а-яё]*',at:'tp1',ch:'vyraz',see:['sv_trop']},
 sv_sravn:{t:'Сравнение (троп)',d:'Сопоставление одного предмета с другим для создания образа: с союзами как, будто, словно, точно, творительным падежом, словами подобный, похож.',ex:'Луна, как бледное пятно…; снег коврами лежит',cat:'Лексика',f:'',at:'tp1',ch:'vyraz',see:['sv_trop','metafora']},
 sv_giperb:{t:'Гипербола',d:'Художественное преувеличение.',ex:'Редкая птица долетит до середины Днепра (Н. В. Гоголь); сто раз говорил',cat:'Лексика',f:'гипербол[а-яё]*',at:'sv6',ch:'vyraz',see:['sv_litota','sv_trop']},
 sv_litota:{t:'Литота',d:'Художественное преуменьшение.',ex:'мальчик с пальчик, мужичок с ноготок',cat:'Лексика',f:'литот[а-яё]*',at:'sv6',ch:'vyraz',see:['sv_giperb','sv_trop']},
 sv_figura:{t:'Фигуры речи',d:'Выразительные построения фраз: инверсия, анафора, градация, антитеза, параллелизм, риторические вопрос, восклицание и обращение.',ex:'«Выхожу один я на дорогу» — инверсия',cat:'Синтаксис и пунктуация',f:'фигур(?:а|ы|у|ой|ам|ами|ах) речи',at:'sv6',ch:'vyraz',see:['sv_inv','sv_anaf','sv_grad','sv_rvopr']},
 sv_inv:{t:'Инверсия',d:'Непривычный порядок слов, который выделяет слово и создаёт выразительность.',ex:'«Выхожу один я на дорогу» (М. Ю. Лермонтов)',cat:'Синтаксис и пунктуация',f:'инверси[а-яё]*',at:'sv6',ch:'vyraz',see:['sv_figura']},
 sv_anaf:{t:'Анафора',d:'Повтор слова или сочетания в начале соседних фраз или строк.',ex:'Нам нужен чистый воздух. Нам нужна живая река.',cat:'Синтаксис и пунктуация',f:'анафор[а-яё]*',at:'sv5',ch:'vyraz',see:['sv_figura','sv_parall']},
 sv_grad:{t:'Градация',d:'Расположение близких по смыслу слов по нарастанию (или ослаблению) значения.',ex:'«Не жалею, не зову, не плачу» (С. А. Есенин)',cat:'Синтаксис и пунктуация',f:'градаци[а-яё]*',at:'sv6',ch:'vyraz',see:['sv_figura']},
 sv_parall:{t:'Синтаксический параллелизм',d:'Одинаковое построение соседних предложений или их частей.',ex:'Лес кормит зверя. Лес поит реку. Лес лечит человека.',cat:'Синтаксис и пунктуация',f:'параллелизм[а-яё]*',at:'sv5',ch:'vyraz',see:['sv_anaf','sv_figura']},
 sv_rvopr:{t:'Риторический вопрос',d:'Вопрос, на который не ждут ответа: он утверждает мысль и усиливает её.',ex:'Разве можно спокойно смотреть, как гибнет родник?',cat:'Синтаксис и пунктуация',f:'риторическ(?:ий|ого|ому|им|ом|ие|их|ими) вопрос[а-яё]*',at:'sv5',ch:'vyraz',see:['sv_rvoskl','sv_robr']},
 sv_rvoskl:{t:'Риторическое восклицание',d:'Восклицание, которое выражает сильное чувство автора.',ex:'Какое богатство мы получили от предков!',cat:'Синтаксис и пунктуация',f:'риторическ(?:ое|ого|ому|им|ом|ие|их|ими) восклицани[а-яё]*',at:'sv5',ch:'vyraz',see:['sv_rvopr','sv_robr']},
 sv_robr:{t:'Риторическое обращение',d:'Обращение к читателю, слушателю или к тому, кто не может ответить; служит выразительности.',ex:'О родная река, сколько ты видела на своём веку!',cat:'Синтаксис и пунктуация',f:'риторическ(?:ое|ого|ому|им|ом|ие|их|ими) обращени[а-яё]*',at:'sv5',ch:'vyraz',see:['sv_rvopr','sv_rvoskl']},
 sv_mnogostil:{t:'Многостильность',d:'Свойство художественного текста: писатель использует средства всех стилей — разговорные реплики, деловые бумаги, термины, просторечие, — чтобы показать героя, время, место.',ex:'письмо Ваньки Жукова в рассказе А. П. Чехова «Ванька»',cat:'Общие понятия',f:'многостильност[а-яё]*',at:'sv6',ch:'stili',see:['sv_hud']},
 rc_chuzh:{t:'Чужая речь',d:'Высказывание другого человека (или свои прежние слова и мысли), включённое в речь рассказчика. Передаётся прямой или косвенной речью, цитатой.',ex:'Друг сказал: «Я приду». Друг сказал, что придёт.',cat:'Синтаксис и пунктуация',f:'чуж(?:ая|ой|ую) реч[а-яё]*',at:'rc1',ch:'rech',see:['rc_pryam','kosv_rech','rc_citata']},
 rc_pryam:{t:'Прямая речь',d:'Чужая речь, переданная дословно, с сохранением её формы; на письме заключается в кавычки или начинается с абзаца с тире. Сопровождается словами автора.',ex:'«Пора домой», — сказал Егор.',cat:'Синтаксис и пунктуация',f:'прям(?:ая|ой|ую) реч[а-яё]*',at:'rc1',ch:'rech',see:['rc_avt','rc_chuzh','kosv_rech']},
 rc_avt:{t:'Слова автора',d:'Предложение (или его часть), которое сообщает, кто говорит и как; стоит перед прямой речью, после неё или разрывает её. В заданиях называют также пояснением или вводящими словами.',ex:'Мама спросила: «Ты поел?» — слова автора «Мама спросила».',cat:'Синтаксис и пунктуация',f:'слова(?:х|ми)? автора',at:'rc1',ch:'rech',see:['rc_pryam']},
 rc_dialog:{t:'Диалог',d:'Разговор двух или нескольких лиц; на письме передаётся репликами — каждая с абзаца после тире или в строку в кавычках, через тире.',ex:'— Ты где? — Дома.',cat:'Синтаксис и пунктуация',f:'диалог[а-яё]*',at:'rc4',ch:'rech',see:['rc_replika','rc_pryam']},
 rc_replika:{t:'Реплика',d:'Высказывание одного участника диалога.',ex:'— Можно войти? — Входите. — две реплики.',cat:'Синтаксис и пунктуация',f:'реплик[а-яё]*',at:'rc4',ch:'rech',see:['rc_dialog']},
 rc_citata:{t:'Цитата',d:'Дословная выдержка из текста или высказывания с указанием источника; оформляется как прямая речь, как часть предложения или без кавычек (стихи, эпиграф).',ex:'Пушкин писал: «Люблю тебя, Петра творенье…»',cat:'Синтаксис и пунктуация',f:'цитат[а-яё]*',at:'sh21',ch:'rech',see:['rc_epigraf','rc_chuzh']},
 rc_epigraf:{t:'Эпиграф',d:'Цитата перед текстом или его частью, которая подсказывает главную мысль; пишется без кавычек, источник — под ним, без скобок.',ex:'эпиграф «Береги честь смолоду» к «Капитанской дочке» А. С. Пушкина',cat:'Синтаксис и пунктуация',f:'эпиграф[а-яё]*',at:'rc6',ch:'rech',see:['rc_citata']},
 // ---- «Типы речи» (tipy): ключи с префиксом tp_ ----
 tp_tip:{t:'Тип речи',d:'Способ изложения мысли в тексте, который зависит от того, что показывает автор: события, признаки предмета или причины и доказательства. Типов речи три: повествование, описание, рассуждение.',ex:'о том, как мальчик поймал рыбу, — повествование; о том, как выглядит озеро, — описание; о том, почему нужно беречь лес, — рассуждение',cat:'Общие понятия',f:'тип(?:ы|а|ов|у|ом|ах|ам|ами|е)? речи',at:'tp1',ch:'tipy',see:['tp_povest','tp_opis','tp_rassuzhd','sv_stil']},
 tp_povest:{t:'Повествование',d:'Тип речи: рассказ о событиях, которые следуют одно за другим. Вопрос: что произошло? что было потом? Строится из зачина, завязки, развития действия, кульминации и развязки; главные средства — глаголы совершенного вида в прошедшем времени и слова последовательности.',ex:'Ямщик поскакал; ветер завыл; сделалась метель.',cat:'Общие понятия',f:'повествовани(?:е|я|ю|ем) как тип(?:а|у|ом)? речи',at:'tp2',ch:'tipy',see:['tp_tip','tp_kompoz','tp_zavyazka']},
 tp_opis:{t:'Описание',d:'Тип речи: изображение предмета, места, человека или состояния через перечень признаков. Вопрос: какой? каков? что в нём есть? Строится от общего впечатления к деталям в выбранном порядке.',ex:'Озеро лежало среди сосен, гладкое и тёмное, как стекло.',cat:'Общие понятия',f:'описани(?:е|я|ю|ем) как тип(?:а|у|ом)? речи',at:'tp3',ch:'tipy',see:['tp_tip','tp_detal','tp_portret','tp_peyzazh','tp_interer']},
 tp_rassuzhd:{t:'Рассуждение',d:'Тип речи: объяснение и доказательство мысли. Вопрос: почему? зачем? верно ли? Строится как тезис — доводы — вывод; части связывают слова причины и следствия (потому что, поэтому, значит).',ex:'Лес нужно беречь: он очищает воздух. Итак, вырубая лес, человек вредит себе.',cat:'Общие понятия',f:'рассуждени(?:е|я|ю|ем) как тип(?:а|у|ом)? речи',at:'tp4',ch:'tipy',see:['tp_tip','tp_tezis','tp_dovod','tp_vyvod']},
 tp_tezis:{t:'Тезис (в рассуждении)',d:'Мысль или положение, истинность которого доказывают. Тезис формулируют чётко, он не меняется по ходу рассуждения и не содержит противоречия.',ex:'Лес нужно беречь.',cat:'Общие понятия',f:'тезис(?:а|у|ом|е)? рассуждени[а-яё]*',at:'tp4',ch:'tipy',see:['tp_dovod','tp_vyvod','tp_rassuzhd']},
 tp_dovod:{t:'Довод (аргумент)',d:'Суждение, которое подтверждает тезис: проверенный факт, пример, данные, мнение авторитетного источника. Довод должен подтверждать именно тезис.',ex:'Деревья очищают воздух и задерживают влагу.',cat:'Общие понятия',f:'довод(?:а|у|ом|е|ы|ов|ам|ами|ах)? в рассуждени[а-яё]*',at:'tp4',ch:'tipy',see:['tp_tezis','tp_vyvod']},
 tp_vyvod:{t:'Вывод (в рассуждении)',d:'Итог рассуждения: тезис, подтверждённый доводами. Начинается словами итак, значит, следовательно, поэтому. Вывод должен следовать из доводов.',ex:'Итак, вырубая лес, человек вредит и себе, и природе.',cat:'Общие понятия',f:'вывод(?:а|у|ом|е)? рассуждени[а-яё]*',at:'tp4',ch:'tipy',see:['tp_tezis','tp_dovod']},
 tp_kompoz:{t:'Композиция',d:'Построение текста: расположение и связь его частей. У повествования: зачин, завязка, развитие действия, кульминация, развязка; у описания: общее впечатление, детали, вывод; у рассуждения: тезис, доводы, вывод.',ex:'композиция рассказа: зачин — завязка — развитие — кульминация — развязка',cat:'Общие понятия',f:'композици(?:я|и|ю|ей) (?:текста|рассказа|повествовани[а-яё]*)',at:'tp2',ch:'tipy',see:['tp_zavyazka','tp_kulm','tp_razvyazka']},
 tp_zavyazka:{t:'Завязка',d:'Первое событие, с которого начинается действие в повествовании.',ex:'Вдруг поплавок нырнул, и леска натянулась, как струна.',cat:'Общие понятия',f:'завязк(?:а|и|е|у|ой)(?= (?:повествовани|рассказа|сюжета|действия))',at:'tp2',ch:'tipy',see:['tp_kompoz','tp_kulm']},
 tp_kulm:{t:'Кульминация',d:'Самый напряжённый момент действия в повествовании; после него напряжение спадает и наступает развязка.',ex:'Лещ показался над водой, и удилище затрещало.',cat:'Общие понятия',f:'кульминаци(?:я|и|ю|ей) (?:повествовани|рассказа|сюжета|действия)[а-яё]*',at:'tp2',ch:'tipy',see:['tp_kompoz','tp_razvyazka']},
 tp_razvyazka:{t:'Развязка',d:'Конец действия в повествовании: чем всё кончилось.',ex:'Отец подхватил рыбу сачком, и лещ забился на траве.',cat:'Общие понятия',f:'развязк(?:а|и|е|у|ой)(?= (?:повествовани|рассказа|сюжета|действия))',at:'tp2',ch:'tipy',see:['tp_kompoz','tp_kulm']},
 tp_detal:{t:'Деталь (в описании)',d:'Характерная подробность, которая делает описание точным и живым. Выразительная деталь говорит о предмете или человеке больше, чем перечень всех признаков.',ex:'зелёная лампа на письменном столе; халат, который засалился до блеска',cat:'Общие понятия',f:'деталь(?:ю|и|ей|ям|ях)? описани[а-яё]*',at:'tp3',ch:'tipy',see:['tp_opis']},
 tp_portret:{t:'Портрет',d:'Описание человека: внешность, одежда, движения. В литературе портрет раскрывает и характер героя.',ex:'Бабушка — невысокая, сухонькая, с седыми волосами, убранными под платок.',cat:'Общие понятия',f:'портрет(?:а|у|ом|е)? героя|описани(?:е|я|ю|ем) человека',at:'tp3',ch:'tipy',see:['tp_opis','tp_peyzazh','tp_interer']},
 tp_peyzazh:{t:'Пейзаж',d:'Описание природы, вида местности. В литературе пейзаж создаёт настроение, служит фоном, помогает передать состояние героя.',ex:'Озеро лежало среди сосен, гладкое и тёмное, как стекло.',cat:'Общие понятия',f:'пейзаж(?:а|у|ем|е|и|ей)? в литератур[а-яё]*|описани(?:е|я|ю|ем) местности',at:'tp3',ch:'tipy',see:['tp_opis','tp_portret','tp_interer']},
 tp_interer:{t:'Интерьер',d:'Описание помещения: обстановка, расположение вещей. Помогает понять жизнь и характер хозяев.',ex:'У окна стоял письменный стол, а над диваном висела карта мира.',cat:'Общие понятия',f:'интерьер(?:а|у|ом|е)? в описани[а-яё]*|описани(?:е|я|ю|ем) помещения',at:'tp3',ch:'tipy',see:['tp_opis','tp_portret','tp_peyzazh']},
 // ---- глава «Текст» (tekst): термины с ключами tk_… ----
 tk_tekst:{t:'Текст',d:'Группа предложений (иногда одно), объединённых общей темой и основной мыслью, связанных между собой по смыслу и грамматически и составляющих законченное целое. Признаки: цельность, связность, законченность, деление на части.',ex:'Вечером пошёл дождь. Он лил всю ночь, и к утру река вышла из берегов.',cat:'Общие понятия',f:'',at:'tk1',ch:'tekst',base:1,see:['tk_tema','tk_mysl','tk_zagolovok']},
 tk_zagolovok:{t:'Заголовок',d:'Название текста. Называет тему («Воробей») или передаёт основную мысль («Любовь сильнее страха»). Должен быть точным, не слишком общим и не слишком узким.',ex:'«Воробей» — заголовок-тема; «Дело мастера боится» — заголовок-мысль',cat:'Общие понятия',f:'заголов(?:ок|ка|ку|ком|ке|ки|ков|кам|ками|ках)',at:'tk1',ch:'tekst',base:1,see:['tk_tekst','tk_tema','tk_mysl']},
 tk_tema:{t:'Тема текста',d:'То, о чём говорится в тексте, его предмет речи; отвечает на вопрос «О чём?» и формулируется словосочетанием.',ex:'встреча охотника с птенцом воробья',cat:'Общие понятия',f:'тем(?:а|ы|е|у|ой) текста|тем(?:а|ы|е|у|ой) высказывания',at:'tk2',ch:'tekst',see:['tk_mysl','tk_klslova','tk_mikrotema']},
 tk_mysl:{t:'Основная мысль',d:'Главный вывод, который автор хочет сказать о предмете речи; отвечает на вопрос «Что хотел сказать автор?» и формулируется предложением. Бывает в начале, в конце, в заголовке или не выражена прямо.',ex:'Любовь сильнее страха смерти.',cat:'Общие понятия',f:'основн(?:ая|ой|ую|ою) мысл(?:ь|и|ью)|основн(?:ые|ых|ым|ыми) мысл(?:и|ей|ям|ями)',at:'tk2',ch:'tekst',see:['tk_tema','tk_klslova','tk_zagolovok']},
 tk_klslova:{t:'Ключевые слова',d:'Слова, которые несут тему текста: они повторяются или заменяются синонимами, однокоренными словами и местоимениями. По ключевым словам можно определить тему.',ex:'в тексте о воробье: воробей, птенец, птица, собака, пёс',cat:'Общие понятия',f:'ключев(?:ые|ых|ым|ыми|ое|ого) слов[а-яё]*',at:'tk2',ch:'tekst',see:['tk_tema','tk_leksp']},
 tk_mikrotema:{t:'Микротема',d:'Тема одной части текста, чаще всего одного абзаца. Из микротем складывается тема всего текста.',ex:'в «Деревне» И. С. Тургенева: овраг с ручьём, избы вдоль оврага, сено перед избами',cat:'Общие понятия',f:'микротем[а-яё]*',at:'tk3',ch:'tekst',see:['tk_abzac','tk_tema']},
 tk_abzac:{t:'Абзац',d:'Отрезок текста от одной красной строки до другой. Обычно в нём раскрывается одна микротема; новый абзац начинают при смене предмета речи, времени, места, говорящего.',ex:'каждая реплика диалога записывается с нового абзаца',cat:'Синтаксис и пунктуация',f:'абзац(?:а|у|ем|е|ы|ев|ам|ами|ах)?|красн(?:ая|ой|ую|ою) строк[а-яё]*',at:'tk3',ch:'tekst',base:1,see:['tk_mikrotema','tk_zachin','tk_ssc']},
 tk_zachin:{t:'Зачин',d:'Начало текста: вводит тему, героев, место и время, привлекает внимание читателя.',ex:'Жила-была на свете лягушка-квакушка.',cat:'Общие понятия',f:'зачин(?:а|у|ом|е|ы|ов)?',at:'tk3',ch:'tekst',see:['tk_koncovka','tk_abzac']},
 tk_koncovka:{t:'Концовка',d:'Окончание текста: подводит итог, делает вывод, оценивает события или оставляет последнее впечатление.',ex:'Но утки уж никогда не вернулись.',cat:'Общие понятия',f:'концовк(?:а|и|е|у|ой|ам|ами|ах)',at:'tk3',ch:'tekst',see:['tk_zachin','tk_abzac']},
 tk_ssc:{t:'Сложное синтаксическое целое',d:'Группа предложений, объединённых одной микротемой и связью друг с другом (повторами, местоимениями, союзами, порядком слов). Часто совпадает с абзацем, но не обязательно.',ex:'Вечером пошёл дождь. Он лил всю ночь. К утру река вышла из берегов.',cat:'Синтаксис и пунктуация',f:'сложн(?:ое|ого|ому|ым|ом) синтаксическ(?:ое|ого|ому|им|ом) цел(?:ое|ого|ому|ым|ом)',at:'tk3',ch:'tekst',see:['tk_abzac','tk_mikrotema']},
 tk_cep:{t:'Цепная связь предложений',d:'Способ связи, при котором каждое следующее предложение подхватывает слово или мысль предыдущего (повтором, местоимением, синонимом) и развивает её.',ex:'В углу стоял сундук. Сундук был обит железом. На нём лежал кот.',cat:'Синтаксис и пунктуация',f:'цепн(?:ая|ой|ую|ою) связ(?:ь|и|ью)',at:'tk4',ch:'tekst',see:['tk_paral','tk_sredstva']},
 tk_paral:{t:'Параллельная связь предложений',d:'Способ связи, при котором предложения построены одинаково (общее начало, порядок слов, форма сказуемых) и перечисляются, сопоставляются или противопоставляются.',ex:'Все молчали. Все ждали. Все смотрели на дверь.',cat:'Синтаксис и пунктуация',f:'параллельн(?:ая|ой|ую|ою) связ(?:ь|и|ью)',at:'tk4',ch:'tekst',see:['tk_cep','tk_sredstva']},
 tk_rema:{t:'Тема и рема',d:'Две части высказывания по смыслу: известное (тема, «данное») и новое (рема, ядро). Рему находят с помощью вопроса, на который отвечает предложение; обычно она стоит в конце.',ex:'Лето я провёл (тема) в деревне (рема).',cat:'Синтаксис и пунктуация',f:'рем(?:а|ы|е|у|ой)|актуальн(?:ое|ого|ому|ым|ом) членени[а-яё]*',at:'tk4',ch:'tekst',see:['tk_poryadok','tk_cep']},
 tk_poryadok:{t:'Порядок слов',d:'Расположение слов в предложении. Бывает прямым (подлежащее перед сказуемым, определение перед определяемым словом) и обратным. В тексте порядок слов помогает связи: известное ставят в начало, новое — в конец.',ex:'Мальчик читает книгу. — Книгу читает мальчик.',cat:'Синтаксис и пунктуация',f:'порядк(?:а|у|ом|е) слов|(?:прям(?:ой|ого|ому|ым)|обратн(?:ый|ого|ому|ым)) порядк[а-яё]*',at:'tk4',ch:'tekst',see:['tk_rema','tk_cep']},
 tk_sredstva:{t:'Средства связи предложений',d:'Все способы объединить предложения в текст: лексические (повтор, синонимы, однокоренные слова), морфологические (местоимения, союзы, частицы, наречия, единая форма времени), синтаксические (вводные слова, порядок слов, параллельное построение).',ex:'Мы вышли в поле. Там было тихо. («Там» — местоименное наречие.)',cat:'Синтаксис и пунктуация',f:'',at:'tk5',ch:'tekst',see:['tk_leksp','tk_cep','tk_paral']},
 tk_leksp:{t:'Лексический повтор',d:'Повторение в соседних предложениях одного слова (или его синонима, однокоренного слова) как средство связи. Намеренный повтор усиливает речь, ненужный — признак бедности речи.',ex:'Мы шли по тропе. Тропа вилась среди ёлок.',cat:'Лексика',f:'лексическ(?:ий|ого|ому|им|ом) повтор(?:а|у|ом|е)?',at:'tk5',ch:'tekst',see:['tk_sredstva','tk_klslova']},
 tk_redakt:{t:'Редактирование',d:'Улучшение текста: поиск и исправление повторов, неясных местоимений, нарушений времени и последовательности, лишних предложений.',ex:'Катя сказала Тане, что она опоздала. → …что Таня опоздала.',cat:'Общие понятия',f:'редактировани(?:е|я|ю|ем|и)',at:'tk5',ch:'tekst',see:['tk_sredstva']},
 tk_plan:{t:'План текста',d:'Перечень основных частей текста в порядке следования; в каждом пункте названа одна микротема. Бывает простым и сложным (с подпунктами), назывным и вопросным.',ex:'1. Происхождение удочки. 2. Части удочки.',cat:'Общие понятия',f:'',at:'tk6',ch:'tekst',see:['tk_tezisy','tk_konspekt']},
 tk_tezisy:{t:'Тезисы',d:'Кратко сформулированные основные положения текста в виде законченных предложений, в порядке следования частей.',ex:'Удочка — одна из первых рыболовных снастей.',cat:'Общие понятия',f:'тезис(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'tk6',ch:'tekst',see:['tk_plan','tk_konspekt']},
 tk_konspekt:{t:'Конспект',d:'Сжатая связная запись содержания, в которой есть план, тезисы и важнейшие примеры; пишется своими словами, ключевые термины сохраняются.',ex:'Удочка — одна из первых снастей. Первобытный человек догадался привязать крючок к нитке…',cat:'Общие понятия',f:'конспект(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'tk6',ch:'tekst',see:['tk_plan','tk_tezisy']},
 tk_pereskaz:{t:'Пересказ',d:'Передача содержания прочитанного своими словами. Бывает подробным, сжатым и выборочным; при сжатии используют исключение, обобщение и упрощение.',ex:'сжатый пересказ рассказа в пяти предложениях',cat:'Общие понятия',f:'пересказ(?:а|у|ом|е|ы|ов|ам|ами|ах)?',at:'tk6',ch:'tekst',base:1,see:['tk_konspekt']},
 tk_annot:{t:'Аннотация',d:'Краткая характеристика книги или статьи: о чём издание, какие вопросы рассматриваются, для кого оно предназначено.',ex:'В книге рассказывается об ужении рыбы. Издание предназначено любителям природы.',cat:'Общие понятия',f:'аннотаци(?:я|и|ю|ей|е|й|ям|ях)',at:'tk6',ch:'tekst',see:['tk_pereskaz','tk_konspekt']},
 vy_zvukopis:{t:'Звукопись',d:'Намеренный подбор и повторение звуков, чтобы строка звучала похоже на то, о чём говорится, или создавала настроение. Приёмы звукописи — аллитерация и ассонанс.',ex:'«Шипенье пенистых бокалов» (А. С. Пушкин): повторяются [ш], [п]',cat:'Фонетика и орфоэпия',f:'звукопис[а-яё]*',at:'vy1',ch:'vyraz',see:['vy_allit','vy_assonans','vy_zvukopodr']},
 vy_allit:{t:'Аллитерация',d:'Повторение одинаковых или сходных согласных звуков для создания звукового образа: шороха, грохота, шипения.',ex:'«Ревёт ли зверь в лесу глухом, / Трубит ли рог, гремит ли гром» (А. С. Пушкин): повторяется [р]',cat:'Фонетика и орфоэпия',f:'аллитераци[а-яё]*',at:'vy1',ch:'vyraz',see:['vy_zvukopis','vy_assonans']},
 vy_assonans:{t:'Ассонанс',d:'Повторение одинаковых гласных звуков. Передаёт гул, протяжность, напев.',ex:'«Мчатся тучи, вьются тучи; / Невидимкою луна» (А. С. Пушкин): повторяется [у]',cat:'Фонетика и орфоэпия',f:'ассонанс[а-яё]*',at:'vy1',ch:'vyraz',see:['vy_zvukopis','vy_allit']},
 vy_zvukopodr:{t:'Звукоподражание',d:'Слово, которое воспроизводит звук природы, животных или предметов. Отличается от звукописи: это отдельное слово, а звукопись — повтор звуков.',ex:'ку-ку, тик-так, жужжать, шуршать, хлоп',cat:'Фонетика и орфоэпия',f:'звукоподражани[а-яё]*|звукоподражательн[а-яё]*',at:'vy1',ch:'vyraz',see:['vy_zvukopis']},
 vy_perifraz:{t:'Перифраза',d:'Описательный оборот, в котором название предмета или явления заменено описанием его существенных признаков.',ex:'царь зверей (вместо лев); автор «Героя нашего времени» (вместо Лермонтов)',cat:'Лексика',f:'перифраз[а-яё]*',at:'vy2',ch:'vyraz',see:['sv_trop','metafora']},
 vy_alleg:{t:'Аллегория',d:'Иносказательное изображение отвлечённого понятия через конкретный образ. Часто встречается в баснях и сказках.',ex:'лиса — хитрость, волк — жадность; птицы в «Песне о Буревестнике» — люди и их отношение к борьбе',cat:'Лексика',f:'аллегори[а-яё]*',at:'vy2',ch:'vyraz',see:['sv_trop','metafora']},
 vy_ironiya:{t:'Ирония',d:'Употребление слова или выражения в смысле, обратном буквальному, с насмешкой. Смысл понятен по контексту и интонации.',ex:'«Хороша педагогия, нечего сказать» (А. П. Чехов)',cat:'Лексика',f:'ирони(?:я|и|ю|ей|ями|ях)|иронич[а-яё]*',at:'rc6',ch:'vyraz',see:['sv_trop']},
 vy_epifora:{t:'Эпифора',d:'Повторение слов или выражений в конце соседних фраз или частей. Закругляет мысль, подчёркивает итог.',ex:'Отчего я титулярный советник и с какой стати я титулярный советник? (Н. В. Гоголь)',cat:'Синтаксис и пунктуация',f:'эпифор[а-яё]*',at:'vy4',ch:'vyraz',see:['sv_anaf','sv_figura']},
 vy_leksp:{t:'Лексический повтор',d:'Повторение слова подряд или рядом, чтобы выделить важное слово или усилить чувство.',ex:'Словом, пошли толки, толки… (Н. В. Гоголь)',cat:'Синтаксис и пунктуация',f:'лексическ[а-яё]* повтор[а-яё]*',at:'vy4',ch:'vyraz',see:['sv_anaf','vy_epifora']},
 vy_mnogosoyuz:{t:'Многосоюзие',d:'Намеренное повторение союзов между однородными членами или частями фразы. Замедляет речь и выделяет каждое звено.',ex:'И шумели деревья, и пели птицы, и текла река.',cat:'Синтаксис и пунктуация',f:'многосоюзи[а-яё]*',at:'vy4',ch:'vyraz',see:['vy_bessoyuz','sv_figura']},
 vy_bessoyuz:{t:'Бессоюзие',d:'Намеренный пропуск союзов в перечислении. Ускоряет речь, показывает быструю смену картин. Не путать с бессоюзным сложным предложением.',ex:'Швед, русский — колет, рубит, режет. (А. С. Пушкин)',cat:'Синтаксис и пунктуация',f:'бессоюзи(?:е|я|ю|ем|и|й|ями|ях)',at:'vy4',ch:'vyraz',see:['vy_mnogosoyuz','bsp']},
 vy_ellips:{t:'Эллипсис',d:'Пропуск члена предложения, который легко восстановить; на месте пропуска часто стоит тире. Придаёт фразе быстроту и живость.',ex:'Рюрик — в Новгород, Синеус — в Ладогу, Трувор — в Изборск.',cat:'Синтаксис и пунктуация',f:'эллипс(?:ис|иса|ису|исом|исе|исы|исов)',at:'vy4',ch:'vyraz',see:['vy_umolch','sv_figura']},
 vy_umolch:{t:'Умолчание',d:'Оборот, в котором мысль нарочно не доведена до конца: читатель сам догадывается о невысказанном. На письме — многоточие.',ex:'Что подумали, что почувствовали оба? Кто узнает? Кто скажет? Есть такие мгновения в жизни, такие чувства… (И. С. Тургенев)',cat:'Синтаксис и пунктуация',f:'умолчани[а-яё]*',at:'vy4',ch:'vyraz',see:['vy_ellips','sv_figura']},
 vy_period:{t:'Период (фигура речи)',d:'Сильно распространённое предложение, законченное по мысли и разделённое интонацией на повышение и понижение. Части периода построены параллельно.',ex:'Как ни старались люди… — весна была весною даже и в городе. (Л. Н. Толстой)',cat:'Синтаксис и пунктуация',f:'',at:'vy4',ch:'vyraz',see:['sv_parall','sv_figura']},
};
